function _icon(emoji, w, h) {
  var svg = _SVG[emoji];
  if (!svg && emoji) {
    svg = _SVG[emoji.replace(/\uFE0F/g, '')];
  }
  if (!svg) return emoji;
  if (w || h) {
    svg = svg.replace('width="1em"', 'width="' + (w || h || 16) + '"');
    svg = svg.replace('height="1em"', 'height="' + (h || w || 16) + '"');
  }
  return svg;
}

var _fullscreenTabId = null;

function canExecInWebview(wv) {
  if (!wv) return false;
  try {
    if (wv.isDestroyed && wv.isDestroyed()) return false;
  } catch(e) { return false; }
  var url = '';
  try { url = wv.getURL ? wv.getURL() : (wv.src || ''); } catch(e) { url = wv.src || ''; }
  if (!url) return false;
  if (url === 'about:blank' || url.indexOf('about:') === 0) return false;
  if (url.indexOf('chrome') === 0) return false;
  if (url.indexOf('file://') === 0) return false;
  return true;
}

var _forceDarkMode = false;

function injectForceDark(webview) {
  if (!webview || !canExecInWebview(webview)) return;
  var url = '';
  try { url = webview.getURL ? webview.getURL() : (webview.src || ''); } catch(e) { return; }
  if (url.indexOf('file://') === 0 || url.indexOf('Settings.html') > -1 || url.indexOf('MainPage/index.html') > -1) return;
  var detectDarkCode =
    '(function(){' +
    'function isDark(c){if(!c||c==="transparent"||c==="rgba(0, 0, 0, 0)")return false;' +
    'var m=c.match(/\\d+/g);if(!m||m.length<3)return false;' +
    'return(+m[0]*0.299+m[1]*0.587+m[2]*0.114)<128;}' +
    'function pageIsDark(){' +
    'var html=document.documentElement;' +
    'if(html.hasAttribute("dark"))return true;' +
    'if(html.getAttribute("color")==="dark")return true;' +
    'var cs=html.getAttribute("color-scheme");if(cs&&cs.indexOf("dark")>=0)return true;' +
    'var meta=document.querySelector("meta[name=color-scheme]");' +
    'if(meta&&(meta.content||"").indexOf("dark")>=0)return true;' +
    'if(html.getAttribute("data-color-mode")==="dark")return true;' +
    'if(html.getAttribute("data-theme")&&html.getAttribute("data-theme").indexOf("dark")>=0)return true;' +
    'if(document.body.getAttribute("data-color-mode")==="dark")return true;' +
    'var hcs=window.getComputedStyle(html);' +
    'var bcs=window.getComputedStyle(document.body);' +
    'if(isDark(hcs.backgroundColor)||isDark(bcs.backgroundColor)){' +
    'if(!isDark(hcs.color)||!isDark(bcs.color))return true;' +
    '}' +
    'return false;' +
    '}' +
    'return pageIsDark();' +
    '})()';
  webview.executeJavaScript(detectDarkCode).then(function(result) {
    if (result) return;
    webview.executeJavaScript(
      '(function(){' +
      'if(document.getElementById("__force_dark_style"))return;' +
      'var s=document.createElement("style");' +
      's.id="__force_dark_style";' +
      's.textContent=' +
      '"html{filter:invert(1) hue-rotate(180deg)!important;background:#000!important}" +' +
      '"html img,html video,html canvas,html picture,html embed,html object[type^=image],html [role=img]{filter:invert(1) hue-rotate(180deg)!important}" +' +
      '"html iframe{filter:invert(1) hue-rotate(180deg)!important}" +' +
      '"html [style*=background-image]{filter:invert(1) hue-rotate(180deg)!important}"' +
      ';document.documentElement.appendChild(s);' +
      '})()'
    ).catch(function() {});
    webview.executeJavaScript(detectDarkCode).then(function(result) {
      if (result) removeForceDark(webview);
    }).catch(function() {});
  }).catch(function() {});
}

function removeForceDark(webview) {
  if (!webview) return;
  webview.executeJavaScript(
    '(function(){var s=document.getElementById("__force_dark_style");if(s)s.remove();})()'
  ).catch(function() {});
}

function toggleForceDark() {
  _forceDarkMode = !_forceDarkMode;
  var btn = document.getElementById('darkModeBtn');
  if (btn) btn.classList.toggle('active', _forceDarkMode);
  tabs.forEach(function(t) {
    if (t.webview && canExecInWebview(t.webview)) {
      if (_forceDarkMode) injectForceDark(t.webview);
      else removeForceDark(t.webview);
    }
  });
}

var _injectedScriptRuns = {};

// List of domains where user scripts and other
// automatic injections are NOT allowed. On login pages (Google, Microsoft, banks, etc.)
// any foreign script = automation marker for BotGuard → login blocked
// with the message "This browser or app may not be secure" (rrk=46).
var _SENSITIVE_AUTH_HOSTS = [
  'accounts.google.com',
  'myaccount.google.com',
  'passwords.google.com',
  'accounts.youtube.com',
  'securetoken.google.com',
  'oauth2.googleapis.com',
  'login.live.com',
  'login.microsoftonline.com',
  'account.live.com',
  'signin.aws.amazon.com',
  'login.yahoo.com'
];
function _isSensitiveAuthPage(url) {
  try {
    var host = new URL(url).hostname.toLowerCase();
    for (var i = 0; i < _SENSITIVE_AUTH_HOSTS.length; i++) {
      var h = _SENSITIVE_AUTH_HOSTS[i];
      if (host === h || host.indexOf('.' + h) === host.length - h.length - 1) return true;
    }
    // Login paths on any domains are also blocked
    if (url.indexOf('/signin') > -1 || url.indexOf('/login') > -1 ||
        url.indexOf('/oauth') > -1 || url.indexOf('/account/login') > -1) return true;
    return false;
  } catch(e) { return false; }
}

function injectUserScripts(webview, pageUrl, opts) {
  if (!webview || !pageUrl) return;
  if (pageUrl.indexOf('file://') === 0 || pageUrl.indexOf('about:') === 0 || pageUrl.indexOf('chrome') === 0) return;
  // Do NOT inject scripts into login pages — BotGuard detects them and blocks login.
  if (_isSensitiveAuthPage(pageUrl)) return;
  try { if (webview.isDestroyed && webview.isDestroyed()) return; } catch(e) { return; }
  if (!window.electronAPI || !window.electronAPI.getScriptsForPage) return;

  var filterRunAt = (opts && opts.runAt) || 'document-idle';
  var isFrame = !!(opts && opts.isFrame);
  var isSpa = !!(opts && opts.isSpa);
  var wvRef = webview;
  var capturedUrl = pageUrl;

  window.electronAPI.getScriptsForPage(capturedUrl).then(function(scripts) {
    if (!scripts || !scripts.length) return;
    try { if (wvRef.isDestroyed && wvRef.isDestroyed()) return; } catch(e) { return; }

    scripts.forEach(function(s) {
      if (!s || !s.code) return;
      if (s.runAt !== filterRunAt && filterRunAt !== '__all__') return;
      if (isFrame && !s.runInFrames) return;

      if (isSpa) {
        var runKey = s.id + ':' + capturedUrl;
        if (_injectedScriptRuns[runKey]) return;
        _injectedScriptRuns[runKey] = true;
        setTimeout(function() { delete _injectedScriptRuns[runKey]; }, 2000);
      }

      wvRef.executeJavaScript('(function(){try{' + s.code + '}catch(e){console.error("[UserScript error]",e)}return 0})()').catch(function() {});
    });
  }).catch(function() {});
}

const urlInput = document.getElementById('urlInput');
const backBtn = document.getElementById('backBtn');
const forwardBtn = document.getElementById('forwardBtn');
const reloadBtn = document.getElementById('reloadBtn');
const homeBtn = document.getElementById('homeBtn');
const libraryBtn = document.getElementById('libraryBtn');
const newTabBtn = document.getElementById('newTabBtn');
const settingsBtn = document.getElementById('settingsBtn');

// Tab management system
let tabs = [];
let activeTabId = null;
let closedTabsHistory = [];
var _tabAudioPlaying = {};
var _tabMuted = {};
var _tabZoom = {};
var _tabPreviewTimer = null;

// ============== GLOBAL SETTINGS (loaded at startup) ==============
let searchEngineUrl = 'https://www.google.com/search?q=';
let currentTheme = 'dark';
var _urlBarFullUrl = '';
var _urlBarRevealed = false;
var _urlBarSearchText = '';
var _urlBarSearchTabId = null;

function setUrlBarDisplay(url) {
  _urlBarFullUrl = url;
  var revealBtn = document.getElementById('urlRevealBtn');
  var showText = '';
  if (_urlBarSearchText && _urlBarSearchTabId === activeTabId && url && url.indexOf('http') === 0) {
    try { var u = new URL(url); var q = u.searchParams.get('q') || u.searchParams.get('query') || u.searchParams.get('text') || u.searchParams.get('search') || u.searchParams.get('p') || ''; if (q) showText = q; } catch(e) {}
  }
  if (!_urlBarRevealed && showText) {
    urlInput.value = showText;
    if (revealBtn) { revealBtn.style.display = ''; revealBtn.classList.remove('revealed'); }
  } else {
    urlInput.value = url;
    if (revealBtn) { if (_urlBarRevealed) revealBtn.classList.add('revealed'); else revealBtn.classList.remove('revealed'); }
  }
}

// Preload path for webviews — loaded asynchronously once
let webviewPreloadPath = '';
(function loadWebviewPreloadPath() {
  if (window.electronAPI && window.electronAPI.getWebviewPreloadPath) {
    window.electronAPI.getWebviewPreloadPath().then(function(p) {
      webviewPreloadPath = p;
      // Update all existing webviews with the preload path
      tabs.forEach(function(tab) {
        if (tab.webview && webviewPreloadPath) {
          tab.webview.setAttribute('preload', webviewPreloadPath);
          // Reload to apply preload (only for internal pages)
          if (tab.webview.src.indexOf('Settings.html') > -1 || tab.webview.src.indexOf('MainPage/index.html') > -1 || tab.webview.src.indexOf('ErrorPage/index.html') > -1) {
            tab.webview.reload();
          }
        }
      });
    }).catch(function() {});
  }
})();

(function setupContextMenuActions() {
  if (window.electronAPI && window.electronAPI.onContextMenuAction) {
    window.electronAPI.onContextMenuAction(function(action) {
      var tab = tabs.find(function(t) { return t.id === activeTabId; });
      if (!tab || !tab.webview || !tab.isReady) return;
      var wv = tab.webview;
      var canExec = canExecInWebview(wv);
      switch (action.type) {
        case 'cut': wv.cut(); break;
        case 'copy': wv.copy(); break;
        case 'paste': wv.paste(); break;
        case 'undo': wv.undo(); break;
        case 'redo': wv.redo(); break;
        case 'selectAll': wv.selectAll(); break;
        case 'replaceMisspelling': wv.replaceMisspelling(action.text); break;
        case 'goBack': if (wv.canGoBack()) wv.goBack(); break;
        case 'goForward': if (wv.canGoForward()) wv.goForward(); break;
        case 'reload': wv.reload(); break;
        case 'print': if (canExec) wv.executeJavaScript('(function(){window.print();return 0})()').catch(function() {}); break;
        case 'viewSource': if (canExec) wv.executeJavaScript('window.location.href').then(function(url) {
          createNewTab('view-source:' + url);
        }).catch(function() {}); break;
        case 'inspectElement': wv.inspectElement(action.x, action.y); break;
        case 'toggleDevTools': wv.toggleDevTools(); break;
        case 'screenshotTool': openScreenshotTool(); break;
        case 'zoomIn':
          var zI = (_tabZoom[action.tabId] || 1) + 0.25;
          if (zI > 3) zI = 3;
          _tabZoom[action.tabId] = zI;
          if (canExec) wv.executeJavaScript('document.body.style.zoom=' + zI).catch(function() {}); break;
        case 'zoomOut':
          var zO = (_tabZoom[action.tabId] || 1) - 0.25;
          if (zO < 0.25) zO = 0.25;
          _tabZoom[action.tabId] = zO;
          if (canExec) wv.executeJavaScript('document.body.style.zoom=' + zO).catch(function() {}); break;
        case 'zoomReset':
          _tabZoom[action.tabId] = 1;
          if (canExec) wv.executeJavaScript('document.body.style.zoom=1').catch(function() {}); break;
        case 'translate':
          if (canExec) wv.executeJavaScript('window.location.href').then(function(url) {
            createNewTab('https://translate.google.com/translate?sl=auto&tl=ru&u=' + encodeURIComponent(url));
          }).catch(function() {}); break;
        case 'qrPage':
          if (canExec) wv.executeJavaScript('window.location.href').then(function(url) {
            createNewTab('https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=' + encodeURIComponent(url));
          }).catch(function() {}); break;
        case 'mediaPlayPause': if (canExec) wv.executeJavaScript('(function(){var v=document.querySelector("video,audio");if(v){v.paused?v.play():v.pause()}return 0})()').catch(function() {}); break;
        case 'mediaMute': if (canExec) wv.executeJavaScript('(function(){var v=document.querySelector("video,audio");if(v){v.muted=!v.muted}return 0})()').catch(function() {}); break;
        case 'mediaPiP': if (canExec) wv.executeJavaScript('(function(){var v=document.querySelector("video");if(v&&v.requestPictureInPicture)v.requestPictureInPicture();return 0})()').catch(function() {}); break;
        case 'copyMediaUrl': if (window.electronAPI && window.electronAPI.contextMenuCopy) window.electronAPI.contextMenuCopy(action.url); break;
        case 'copyImage':
          fetch(action.url).then(function(r) { return r.blob(); }).then(function(b) {
            var reader = new FileReader();
            reader.onload = function() {
              if (window.electronAPI && window.electronAPI.contextMenuCopyImage) {
                window.electronAPI.contextMenuCopyImage(reader.result);
              }
            };
            reader.readAsDataURL(b);
          }).catch(function() {});
          break;
        case 'duplicateTab':
          if (canExec) wv.executeJavaScript('window.location.href').then(function(url) {
            createNewTab(url);
          }).catch(function() {}); break;
        case 'closeTab': if (action.tabId) closeTab(action.tabId); break;
        case 'closeOtherTabs':
          var keepId = action.tabId;
          tabs.slice().forEach(function(t) { if (t.id !== keepId) closeTab(t.id); });
          break;
        case 'closeTabsToRight':
          var idx = tabs.findIndex(function(t) { return t.id === action.tabId; });
          if (idx >= 0) tabs.slice(idx + 1).forEach(function(t) { closeTab(t.id); });
          break;
        case 'closeTabsFromDomain':
          var domain = action.domain;
          tabs.slice().forEach(function(t) {
            try {
              var u = t.webview.getURL ? t.webview.getURL() : (t.webview.src || '');
              if (u.indexOf(domain) !== -1 && t.id !== activeTabId) closeTab(t.id);
            } catch(e) {}
          });
          break;
        case 'reloadAllTabs':
          tabs.forEach(function(t) { try { if (t.isReady) t.webview.reload(); } catch(e) {} });
          break;
        case 'sleepOthers': {
          var sleptCount = sleepAllTabsExceptActive();
          try { _showToast && _showToast('Tabs put to sleep: ' + sleptCount); } catch(e) {}
          break;
        }
        case 'sleepTab':
          var sleepId = action.tabId;
          var sleepTab = tabs.find(function(t) { return t.id === sleepId; });
          if (sleepTab && sleepTab.webview && sleepTab.isReady && !sleepTab._isSleeping && sleepId !== activeTabId) {
            try {
              var sleepUrl2 = sleepTab.webview.getURL ? sleepTab.webview.getURL() : sleepTab.webview.src;
              if (sleepUrl2 && sleepUrl2 !== 'about:blank' && !isDomainNoSleep(sleepUrl2)) {
                _maybeClearSWBeforeSleep(sleepTab);
                sleepTab._sleepUrl = sleepUrl2;
                sleepTab.pendingUrl = sleepUrl2;
                sleepTab.lastUrl = null;
                try { sleepTab.webview.loadURL('about:blank'); } catch(e) {}
                sleepTab._isSleeping = true;
                sleepTab.isReady = false;
                var sleepEl = document.querySelector('[data-tab-id="' + sleepId + '"]');
                if (sleepEl) {
                  sleepEl.classList.add('tab-sleeping');
                  var sleepFav = sleepEl.querySelector('.tab-favicon, .tab-favicon-placeholder');
                  if (sleepFav) sleepFav.classList.add('tab-sleeping-favicon');
                }
              }
            } catch(e) {}
          }
          break;
        case 'reopenTab':
          if (action.url) {
            createNewTab(action.url);
            if (action.index !== undefined && closedTabsHistory[action.index]) {
              closedTabsHistory.splice(action.index, 1);
            }
          }
          break;
        case 'closeAfter':
          if (action.tabId && action.minutes) setTabCloseAfter(action.tabId, action.minutes);
          break;
        case 'closeAfterCancel':
          if (action.tabId) cancelTabCloseAfter(action.tabId);
          break;
        case 'elementZapper':
          if (canExecInWebview(wv)) {
            wv.executeJavaScript('if(window.electronAPI&&window.electronAPI.startElementPicker){window.electronAPI.startElementPicker();return 1}return 0').catch(function() {});
          }
          break;
        case 'pasteAndGo':
          if (window.electronAPI && window.electronAPI.readClipboard) {
            window.electronAPI.readClipboard().then(function(text) {
              if (text) navigateTo(text);
            }).catch(function() {});
          }
          break;
        case 'openIncognito':
          if (action.url && window.createIncognitoTab) window.createIncognitoTab(action.url);
          break;
        case 'openIncognitoPage':
          if (canExecInWebview(wv)) {
            wv.executeJavaScript('window.location.href').then(function(url) {
              if (url && window.createIncognitoTab) window.createIncognitoTab(url);
            }).catch(function() {});
          }
          break;
        case 'colorPicker':
          toggleColorPicker();
          break;
        case 'readerMode':
          if (window._toggleReader) window._toggleReader();
          break;
        case 'pinTab':
          var pinTab = tabs.find(function(t) { return t.id === action.tabId; });
          if (pinTab) {
            pinTab.pinned = !!action.pinned;
            _updatePinStyle(pinTab.id);
            _sortTabsByPinAndGroup();
          }
          break;
        case 'createGroup':
          customPrompt('Group name:', 'Group ' + (_tabGroups.length + 1)).then(function(cgp) {
            if (cgp) {
              var colors = ['#4a90d9','#e74c3c','#2ecc71','#f39c12','#9b59b6','#e91e90','#1abc9c'];
              var newGroup = { id: 'grp-' + Date.now(), name: cgp, color: colors[_tabGroups.length % colors.length], collapsed: false };
              _tabGroups.push(newGroup);
              if (action.tabId) {
                var tgt = tabs.find(function(t) { return t.id === action.tabId; });
                if (tgt) { tgt.groupId = newGroup.id; _applyGroupColor(tgt.id); }
              }
              _saveTabGroups();
              _sortTabsByPinAndGroup();
            }
          });
          break;
        case 'addToGroup':
          var atg = tabs.find(function(t) { return t.id === action.tabId; });
          if (atg) { atg.groupId = action.groupId; _applyGroupColor(atg.id); _sortTabsByPinAndGroup(); }
          break;
        case 'removeFromGroup':
          var rfg = tabs.find(function(t) { return t.id === action.tabId; });
          if (rfg) { rfg.groupId = null; rfg.element.style.borderLeft = ''; _sortTabsByPinAndGroup(); }
          break;
        case 'colorGroup':
          var cg = _tabGroups.find(function(g) { return g.id === action.groupId; });
          if (cg) { cg.color = action.color; _saveTabGroups(); tabs.forEach(function(t) { if (t.groupId === cg.id) _applyGroupColor(t.id); }); _renderTabGroupHeaders(); }
          break;
        case 'deleteGroup':
          _tabGroups = _tabGroups.filter(function(g) { return g.id !== action.groupId; });
          tabs.forEach(function(t) { if (t.groupId === action.groupId) { t.groupId = null; t.element.style.borderLeft = ''; } });
          _saveTabGroups();
          _sortTabsByPinAndGroup();
          break;
      }
    });
  }
})();

// ============== CUSTOM DIALOG SYSTEM ==============
var _dialogResolve = null;
var _dialogQueue = [];
var _dialogOverlay = document.getElementById('dialogOverlay');
var _dialogBox = document.getElementById('dialogBox');
var _dialogIcon = document.getElementById('dialogIcon');
var _dialogMessage = document.getElementById('dialogMessage');
var _dialogInput = document.getElementById('dialogInput');
var _dialogCancel = document.getElementById('dialogCancel');
var _dialogOk = document.getElementById('dialogOk');

function _showDialogInternal(opts, resolve) {
    _dialogResolve = resolve;
    _dialogMessage.textContent = opts.message || '';
    _dialogIcon.textContent = opts.icon || '';

    if (opts.type === 'prompt') {
      _dialogInput.style.display = 'block';
      _dialogInput.value = opts.defaultText || '';
      _dialogCancel.style.display = 'inline-flex';
      _dialogCancel.textContent = opts.cancelText || 'Cancel';
      _dialogOk.textContent = opts.okText || 'OK';
      setTimeout(function() { _dialogInput.focus(); _dialogInput.select(); }, 50);
    } else if (opts.type === 'confirm') {
      _dialogInput.style.display = 'none';
      _dialogCancel.style.display = 'inline-flex';
      _dialogCancel.textContent = opts.cancelText || 'Cancel';
      _dialogOk.textContent = opts.okText || 'OK';
    } else {
      _dialogInput.style.display = 'none';
      _dialogCancel.style.display = 'none';
      _dialogOk.textContent = opts.okText || 'OK';
    }

    _dialogOverlay.classList.add('active');
    _dialogOk.focus();
}

function showCustomDialog(opts) {
  return new Promise(function(resolve) {
    if (_dialogResolve) {
      _dialogQueue.push({ opts: opts, resolve: resolve });
      return;
    }
    _showDialogInternal(opts, resolve);
  });
}

function closeCustomDialog(result) {
  _dialogOverlay.classList.remove('active');
  var resolve = _dialogResolve;
  _dialogResolve = null;
  if (resolve) resolve(result);
  if (_dialogQueue.length > 0) {
    var next = _dialogQueue.shift();
    _showDialogInternal(next.opts, next.resolve);
  }
}

_dialogOk.addEventListener('click', function() {
  if (_dialogInput.style.display !== 'none') {
    closeCustomDialog(_dialogInput.value);
  } else {
    closeCustomDialog(true);
  }
});

_dialogCancel.addEventListener('click', function() {
  if (_dialogInput.style.display !== 'none') {
    closeCustomDialog(null);
  } else {
    closeCustomDialog(false);
  }
});

_dialogInput.addEventListener('keydown', function(e) {
  if (e.key === 'Enter') {
    e.preventDefault();
    closeCustomDialog(_dialogInput.value);
  }
});

_dialogOverlay.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') {
    e.preventDefault();
    if (_dialogInput.style.display !== 'none') {
      closeCustomDialog(null);
    } else {
      closeCustomDialog(false);
    }
  }
});

function customAlert(msg) {
  return showCustomDialog({ type: 'alert', message: msg, icon: '\u2139\uFE0F' });
}

function customConfirm(msg) {
  return showCustomDialog({ type: 'confirm', message: msg, icon: '\u2753' });
}

function customPrompt(msg, def) {
  return showCustomDialog({ type: 'prompt', message: msg, defaultText: def || '', icon: '\u270F\uFE0F' });
}

// Webview dialog handler (alert/confirm/prompt from web pages)
(function setupWebviewDialogHandler() {
  if (window.electronAPI && window.electronAPI.onWebviewDialog) {
    window.electronAPI.onWebviewDialog(function(data) {
      var icons = { alert: '\u2139\uFE0F', confirm: '\u2753', prompt: '\u270F\uFE0F', beforeunload: '\u26A0\uFE0F' };
      var okTexts = { alert: 'OK', confirm: 'OK', prompt: 'OK', beforeunload: '\u0423\u0439\u0442\u0438' };
      var cancelTexts = { beforeunload: '\u041E\u0441\u0442\u0430\u0442\u044C\u0441\u044F' };
      showCustomDialog({
        type: data.type,
        message: data.message || '',
        defaultText: data.defaultText || '',
        icon: icons[data.type] || '\u2139\uFE0F',
        okText: okTexts[data.type] || 'OK',
        cancelText: cancelTexts[data.type] || '\u041E\u0442\u043C\u0435\u043D\u0430'
      }).then(function(result) {
        if (window.electronAPI && window.electronAPI.respondWebviewDialog) {
          window.electronAPI.respondWebviewDialog(data.dialogId, result);
        }
      });
    });
  }
})();

// Permission request dialog
(function setupPermissionHandler() {
  if (window.electronAPI && window.electronAPI.onPermissionRequest) {
    window.electronAPI.onPermissionRequest(function(data) {
      var existing = document.getElementById('__perm_popup');
      if (existing) existing.remove();
      var popup = document.createElement('div');
      popup.id = '__perm_popup';
      popup.style.cssText = 'position:fixed;top:42px;left:50%;transform:translateX(-50%);z-index:99999;background:var(--bg-color);border:1px solid var(--border-color);border-radius:10px;padding:12px 16px;box-shadow:0 6px 24px rgba(0,0,0,0.4);display:flex;align-items:center;gap:12px;max-width:500px;width:92%;';
      var permLabels = {
        media: 'Media',
        geolocation: 'Geolocation', notifications: 'Notifications',
        midi: 'MIDI', midiSysex: 'MIDI', fullscreen: 'Fullscreen',
        openExternal: 'External links', clipboardRead: 'Clipboard read',
        clipboardWrite: 'Clipboard write', pointerLock: 'Pointer lock',
        persistentStorage: 'Storage'
      };
      var label = permLabels[data.permission] || data.permission;
      var info = document.createElement('div');
      info.style.cssText = 'flex:1;min-width:0;';
      info.innerHTML = '<div style="font-size:12px;font-weight:600;color:var(--text-color);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escapeHtmlSimple(data.domain) + '</div><div style="font-size:11px;color:var(--text-secondary);margin-top:2px;">Requests: <strong style="color:var(--text-color)">' + escapeHtmlSimple(label) + '</strong></div>';
      var btnDeny = document.createElement('button');
      btnDeny.textContent = 'Block';
      btnDeny.style.cssText = 'padding:5px 12px;border-radius:5px;border:1px solid var(--border-color);background:var(--bg-color);color:var(--text-color);cursor:pointer;font-size:12px;white-space:nowrap;';
      var btnAllow = document.createElement('button');
      btnAllow.textContent = 'Allow';
      btnAllow.style.cssText = 'padding:5px 12px;border-radius:5px;border:none;background:var(--primary-color);color:#fff;cursor:pointer;font-size:12px;white-space:nowrap;';
      btnDeny.onclick = function() {
        popup.remove();
        if (window.electronAPI && window.electronAPI.respondPermissionRequest) window.electronAPI.respondPermissionRequest(data.dialogId, false);
      };
      btnAllow.onclick = function() {
        popup.remove();
        if (window.electronAPI && window.electronAPI.respondPermissionRequest) window.electronAPI.respondPermissionRequest(data.dialogId, true);
      };
      popup.appendChild(info);
      popup.appendChild(btnDeny);
      popup.appendChild(btnAllow);
      document.body.appendChild(popup);
    });
  }
})();

