var _qcWidgetVisible = false;

function toggleQcWidget() {
  var existing = document.getElementById('qcWidget');
  if (existing) { existing.remove(); _qcWidgetVisible = false; return; }
  if (_qcVisible) toggleQuickCommands();
  _qcWidgetVisible = true;
  var w = document.createElement('div');
  w.id = 'qcWidget';
  w.innerHTML = '<input type="text" id="qcWidgetInput" placeholder="Quick command..." spellcheck="false">' +
    '<div class="qc-widget-list" id="qcWidgetList"></div>' +
    '<div class="qc-widget-hint">Esc — close · Enter — run</div>';
  document.body.appendChild(w);
  var wInput = document.getElementById('qcWidgetInput');
  var wList = document.getElementById('qcWidgetList');
  setTimeout(function() { wInput.focus(); }, 80);
  wInput.addEventListener('input', function() {
    var q = wInput.value.trim().replace(/^:/, '');
    if (!q) { wList.innerHTML = ''; return; }
    var results = [];
    var qLower = q.toLowerCase();
    _qcCommands.forEach(function(cmd) {
      if (cmd.name.indexOf(qLower) === 0 || cmd.desc.toLowerCase().indexOf(qLower) >= 0) {
        results.push(cmd);
      }
    });
    _qcCustomCommands.forEach(function(c) {
      if (c.name.indexOf(qLower) === 0 || c.desc.toLowerCase().indexOf(qLower) >= 0) {
        results.push({ name: c.name, desc: c.desc, fn: function() {
          if (c.type === 'js') { var t = getActiveTab(); if (t && canExecInWebview(t.webview)) t.webview.executeJavaScript(c.value).catch(function() {}); }
          else { navigateTo(c.value); }
          w.remove(); _qcWidgetVisible = false;
        }});
      }
    });
    if (results.length === 0) { wList.innerHTML = '<div style="padding:8px;color:#999;font-size:12px">Not found</div>'; return; }
    wList.innerHTML = results.slice(0, 6).map(function(cmd, i) {
      return '<div class="qc-widget-item" data-idx="' + i + '"><span style="color:#3b7dd8;margin-right:6px;font-weight:600">:' + escapeHtmlSimple(cmd.name) + '</span><span style="color:#999;font-size:11px">' + escapeHtmlSimple(cmd.desc) + '</span></div>';
    }).join('');
    wList.querySelectorAll('.qc-widget-item').forEach(function(el) {
      el.addEventListener('click', function() {
        var idx = parseInt(el.getAttribute('data-idx'));
        if (results[idx]) { results[idx].fn(); }
      });
    });
  });
  wInput.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') { w.remove(); _qcWidgetVisible = false; }
    if (e.key === 'Enter') {
      var firstItem = wList.querySelector('.qc-widget-item');
      if (firstItem) firstItem.click();
    }
  });
}

function doTranslate(text, from, to, qcInput) {
  if (!window.electronAPI || !window.electronAPI.translateText) return;
  var list = document.getElementById('qcList');
  if (!list) return;
  list.innerHTML = '<div class="qc-empty" style="padding:14px">Translating...</div>';
  window.electronAPI.translateText(text, from, to).then(function(result) {
    if (result.success) {
      if (result.from === result.to) {
        var langLabel = result.to === 'ru' ? 'Russian' : 'English';
        list.innerHTML = '<div class="qc-translate-result">' +
          '<div class="qc-translate-original">' + escapeHtmlSimple(text) + '</div>' +
          '<div class="qc-translate-arrow" style="color:#999">Already in ' + langLabel + '</div>' +
          '<div class="qc-translate-actions">' +
          '<button class="qc-translate-copy" onclick="navigator.clipboard.writeText(\'' + escapeHtmlSimple(text).replace(/'/g, "\\'") + '\');this.textContent=\'Copied!\'">Copy</button>' +
          '</div></div>';
        return;
      }
      var html = '<div class="qc-translate-result">' +
        '<div class="qc-translate-original">' + escapeHtmlSimple(text) + '</div>' +
        '<div class="qc-translate-arrow">\u2193</div>' +
        '<div class="qc-translate-translated">' + escapeHtmlSimple(result.translated) + '</div>' +
        '<div class="qc-translate-actions">' +
        '<button class="qc-translate-copy" onclick="navigator.clipboard.writeText(\'' + escapeHtmlSimple(result.translated).replace(/'/g, "\\'") + '\');this.textContent=\'Copied!\'">Copy</button>' +
        '</div></div>';
      list.innerHTML = html;
    } else {
      list.innerHTML = '<div class="qc-empty" style="padding:14px;color:#e74c3c">Error: ' + escapeHtmlSimple(result.error || 'failed to translate') + '</div>';
    }
  }).catch(function() {
    list.innerHTML = '<div class="qc-empty" style="padding:14px;color:#e74c3c">Network error</div>';
  });
}

// Helper for vim commands in QC: calls window.__spzVimExec in the active tab.
// If vim is not enabled — shows a hint. arg is optional.
function _vimExecInActive(action, arg) {
  var t = getActiveTab();
  if (!t || !t.webview || !canExecInWebview(t.webview)) {
    if (typeof _showToast === 'function') _showToast('Tab not ready', 'vim', null, 'warn');
    return;
  }
  var js = 'window.__spzVimExec && window.__spzVimExec(' + JSON.stringify(action) + (arg !== undefined ? (', ' + JSON.stringify(arg)) : '') + ');';
  t.webview.executeJavaScript(js).then(function(res){
    if (res === false || res === undefined) {
      // Maybe vim is disabled — check and offer to enable
      t.webview.executeJavaScript('window.__spzVimExec && window.__spzVimExec("isEnabled");').then(function(on){
        if (!on && typeof _showToast === 'function') {
          _showToast('Vim is disabled. Enable: :vim-on', 'vim', null, 'warn');
        }
      }).catch(function(){});
    }
  }).catch(function(){
    if (typeof _showToast === 'function') _showToast('Failed to execute vim command', 'vim', null, 'danger');
  });
}
// Re-filter the QC list (for the :vim prefix)
function _qcRenderFiltered(prefixLower) {
  var qi = document.getElementById('qcInput');
  if (qi && typeof qi.dispatchEvent === 'function') {
    qi.dispatchEvent(new Event('input'));
  }
}

var _qcCommands = [
  { name: 'back', desc: 'Back in tab history', cat: 'nav', args: '', fn: function() { var t=getActiveTab(); if(t&&t.webview&&t.isReady){try{if(t.webview.canGoBack())t.webview.goBack();}catch(e){}} }},
  { name: 'forward', desc: 'Forward in tab history', cat: 'nav', args: '', fn: function() { var t=getActiveTab(); if(t&&t.webview&&t.isReady){try{if(t.webview.canGoForward())t.webview.goForward();}catch(e){}} }},
  { name: 'home', desc: 'Open start page', cat: 'nav', args: '', fn: function() { createNewTab('MainPage/index.html'); }},
  { name: 'open', desc: 'Open URL in current tab', cat: 'nav', args: 'URL', fn: function(a) { if(a)navigateTo(a); }},
  { name: 'reload', desc: 'Reload page', cat: 'nav', args: '', fn: function() { var t=getActiveTab(); if(t&&t.webview){try{t.webview.reload();}catch(e){}} }},
  { name: 'stop', desc: 'Stop loading', cat: 'nav', args: '', fn: function() { var t=getActiveTab(); if(t&&t.webview){try{if(t.webview.isLoading&&t.webview.isLoading())t.webview.stop();}catch(e){}} }},
  { name: 'tab-next', desc: 'Next tab', cat: 'tab', args: '', fn: function() { var i=tabs.findIndex(function(t){return t.id===activeTabId;}); if(i>=0){var n=i>=tabs.length-1?0:i+1;setActiveTab(tabs[n].id);} }},
  { name: 'tab-prev', desc: 'Previous tab', cat: 'tab', args: '', fn: function() { var i=tabs.findIndex(function(t){return t.id===activeTabId;}); if(i>=0){var n=i<=0?tabs.length-1:i-1;setActiveTab(tabs[n].id);} }},
  { name: 'tab-close', desc: 'Close tab', cat: 'tab', args: '', fn: function() { closeTab(activeTabId); }},
  { name: 'tab-clone', desc: 'Duplicate tab', cat: 'tab', args: '', fn: function() { var t=getActiveTab(); if(t&&t.webview&&t.isReady&&canExecInWebview(t.webview)){t.webview.executeJavaScript('window.location.href').then(function(u){createNewTab(u);}).catch(function(){});} }},
  { name: 'tab-only', desc: 'Close all tabs except current', cat: 'tab', args: '', fn: function() { tabs.slice().forEach(function(t){if(t.id!==activeTabId)closeTab(t.id);}); }},
  { name: 'tab-focus', desc: 'Go to tab by index', cat: 'tab', args: 'index', fn: function(a) { var n=parseInt(a); if(!isNaN(n)){var idx=n>=1?n-1:n;if(idx>=0&&idx<tabs.length)setActiveTab(tabs[idx].id);} }},
  { name: 'tab-mute', desc: 'Mute tab', cat: 'tab', args: '', fn: function() { var t=getActiveTab(); if(t){_tabMuted[t.id]=true;updateTabAudioIcon(t.id);if(canExecInWebview(t.webview)){t.webview.executeJavaScript('(function(){var els=document.querySelectorAll("video,audio");for(var i=0;i<els.length;i++){els[i].muted=true;}})()').catch(function(){});}} }},
  { name: 'tab-unmute', desc: 'Unmute tab', cat: 'tab', args: '', fn: function() { var t=getActiveTab(); if(t){_tabMuted[t.id]=false;updateTabAudioIcon(t.id);if(canExecInWebview(t.webview)){t.webview.executeJavaScript('(function(){var els=document.querySelectorAll("video,audio");for(var i=0;i<els.length;i++){els[i].muted=false;}})()').catch(function(){});}} }},
  { name: 'tab-pin', desc: 'Pin/unpin tab', cat: 'tab', args: '', fn: function() { var t=getActiveTab(); if(t){t.pinned=!t.pinned;_updatePinStyle(t.id);_sortTabsByPinAndGroup();} }},
  { name: 'tab-group', desc: 'Create group from tab', cat: 'tab', args: 'name', fn: function(a) { var t=getActiveTab(); if(!t)return;var name=a||('Group '+(_tabGroups.length+1));var colors=['#4a90d9','#e74c3c','#2ecc71','#f39c12','#9b59b6','#e91e90','#1abc9c'];var g={id:'grp-'+Date.now(),name:name,color:colors[_tabGroups.length%colors.length],collapsed:false};_tabGroups.push(g);t.groupId=g.id;_applyGroupColor(t.id);_saveTabGroups();_sortTabsByPinAndGroup(); }},
  { name: 'tab-ungroup', desc: 'Remove tab from group', cat: 'tab', args: '', fn: function() { var t=getActiveTab(); if(t&&t.groupId){t.groupId=null;t.element.style.borderLeft='';_sortTabsByPinAndGroup();} }},
  { name: 'bookmark-add', desc: 'Add current page to bookmarks', cat: 'bm', args: '', fn: function() { var t=getActiveTab(); if(t&&t.webview&&t.isReady){var u='';try{u=t.webview.getURL?t.webview.getURL():t.webview.src;}catch(e){}var ti='';try{ti=t.webview.getTitle?t.webview.getTitle():'';}catch(e){}if(u&&u.indexOf('file://')!==0&&window.electronAPI&&window.electronAPI.addBookmark)window.electronAPI.addBookmark({url:u,title:ti||u});} }},
  { name: 'bookmark-list', desc: 'Open bookmarks', cat: 'bm', args: '', fn: function() { createNewTab('Settings.html#bookmarks'); }},
  { name: 'history', desc: 'Open history', cat: 'hist', args: '', fn: function() { createNewTab('Settings.html#history'); }},
  { name: 'history-clear', desc: 'Clear history', cat: 'hist', args: '', fn: function() { if(window.electronAPI&&window.electronAPI.clearHistory)window.electronAPI.clearHistory(); }},
  { name: 'set', desc: 'Set option', cat: 'cfg', args: 'option value', fn: function(a) { if(!a)return;var p=a.split(/\s+/);if(p.length>=2){var k=p[0],v=p.slice(1).join(' ');if(k==='searchengine'&&window.electronAPI&&window.electronAPI.setSearchEngine)window.electronAPI.setSearchEngine(v);if(k==='theme'&&window.electronAPI&&window.electronAPI.setTheme)window.electronAPI.setTheme(v);} }},
  { name: 'hint', desc: 'Hint mode (keyboard links)', cat: 'link', args: '', fn: function() { var t=getActiveTab(); if(t&&canExecInWebview(t.webview)){t.webview.executeJavaScript('(function(){var links=document.querySelectorAll("a[href]");var existing=document.querySelectorAll(".__hint_label");for(var i=0;i<existing.length;i++)existing[i].remove();if(links.length===0)return;var style=document.getElementById("__hint_style");if(!style){style=document.createElement("style");style.id="__hint_style";style.textContent=".__hint_label{position:fixed;background:rgba(255,200,0,0.95);color:#000;font-size:11px;font-weight:bold;padding:2px 5px;border-radius:3px;z-index:2147483647;pointer-events:none;font-family:monospace;border:1px solid #000}";document.head.appendChild(style);}var hintChars="asdfghjkl";var idx=0;function getHint(n){var s="";n++;do{n--;s+=hintChars[n%hintChars.length];n=Math.floor(n/hintChars.length);}while(n>0);return s;}for(var i=0;i<Math.min(links.length,30);i++){var r=links[i].getBoundingClientRect();if(r.width<1||r.height<1||r.bottom<0||r.top>window.innerHeight)continue;var label=document.createElement("span");label.className="__hint_label";label.textContent=getHint(idx);label.style.left=(r.left+2)+"px";label.style.top=(r.top+2)+"px";links[i].setAttribute("__hint_idx",idx);links[i].setAttribute("__hint_key",getHint(idx));document.body.appendChild(label);idx++;}})()').catch(function(){});} }},
  { name: 'jseval', desc: 'Run JavaScript', cat: 'link', args: 'code', fn: function(a) { if(!a)return; var t=getActiveTab(); if(t&&canExecInWebview(t.webview)){t.webview.executeJavaScript(a).catch(function(){});} }},
  { name: 'download-open', desc: 'Open latest download', cat: 'dl', args: '', fn: function() { if(window.electronAPI&&window.electronAPI.getDownloads)window.electronAPI.getDownloads().then(function(dls){if(dls&&dls.length>0){var last=dls[dls.length-1];if(window.electronAPI&&window.electronAPI.openDownloadFile)window.electronAPI.openDownloadFile(last.path);}}).catch(function(){}); }},
  { name: 'print', desc: 'Print page', cat: 'misc', args: '', fn: function() { var t=getActiveTab(); if(t&&canExecInWebview(t.webview)){t.webview.executeJavaScript('window.print()').catch(function(){});} }},
  { name: 'view-source', desc: 'Page source', cat: 'misc', args: '', fn: function() { var t=getActiveTab(); if(t&&t.webview&&t.isReady&&canExecInWebview(t.webview)){t.webview.executeJavaScript('window.location.href').then(function(u){createNewTab('view-source:'+u);}).catch(function(){});} }},
  { name: 'zoom', desc: 'Set zoom (%)', cat: 'misc', args: 'percent', fn: function(a) { var t=getActiveTab(); if(!t)return;var z=a?parseInt(a)/100:1;if(isNaN(z))z=1;z=Math.max(0.25,Math.min(3,z));_tabZoom[t.id]=z;if(canExecInWebview(t.webview)){t.webview.executeJavaScript('document.body.style.zoom='+z).catch(function(){});} }},
  { name: 'fullscreen', desc: 'Fullscreen mode', cat: 'misc', args: '', fn: function() { if(window.electronAPI&&window.electronAPI.toggleWindowFullscreen)window.electronAPI.toggleWindowFullscreen(); }},
  { name: 'version', desc: 'Version info', cat: 'misc', args: '', fn: function() { customAlert('StartPOZI Browser\nElectron '+process.versions.electron+'\nChromium '+process.versions.chrome); }},
  { name: 'quit', desc: 'Quit browser', cat: 'misc', args: '', fn: function() { if(window.electronAPI&&window.electronAPI.windowClose)window.electronAPI.windowClose(); }},
  { name: 'undo', desc: 'Reopen last closed tab', cat: 'tab', args: '', fn: function() { if(closedTabsHistory.length>0){var c=closedTabsHistory.shift();createNewTab(c.url);} }},
  { name: 'help', desc: 'List of all commands (help 2 — page 2)', cat: 'misc', args: '', keepOpen: true, fn: function(a, qcInput) { qcInput.value=':'; var p=parseInt(a); _qcHelpPage=(!isNaN(p)&&p>=1)?p-1:0; renderQcList(':'); }},
  { name: 'reader', desc: 'Reader mode', cat: 'misc', args: '', fn: function() { if (window._toggleReader) window._toggleReader(); }},
  { name: 'sidebar', desc: 'Bookmarks bar', cat: 'misc', args: '', fn: function() { var sb=document.getElementById('bookmarksSidebar'); if(sb){sb.classList.add('open');document.getElementById('sidebarOverlay').classList.add('active');} }},
  { name: 'split', desc: 'Split screen', cat: 'misc', args: '', fn: function() { document.getElementById('splitBtn').click(); }},
  { name: 'incognito', desc: 'Open incognito tab', cat: 'misc', args: '', fn: function() { if(typeof promptIncognitoUrl==='function')promptIncognitoUrl(); }},
  { name: 'clear-data', desc: 'Clear all data (cache, cookies, SW) — full reset', cat: 'misc', args: '', fn: function() {
    if (!window.electronAPI || !window.electronAPI.clearBrowsingData) { customAlert('Unavailable'); return; }
    customConfirm('Clear ALL data: cache, cookies, service workers, localStorage, IndexedDB? This will log you out of all sites.').then(function(ok) {
      if (!ok) return;
      window.electronAPI.clearBrowsingData({}, {
        cache: true, cookies: true, localStorage: true, indexedDB: true,
        serviceWorkers: true, cacheStorage: true, history: false
      }).then(function(r) {
        customAlert('✓ Cleared: cache, cookies, service workers, IndexedDB.\nRestart the browser and try again.');
      }).catch(function(e) { customAlert('Error: ' + (e && e.message || 'unknown')); });
    });
  }},
  { name: 'profile-switch', desc: 'Switch profile', cat: 'misc', args: 'name', fn: function(a) { if(!a||!window.electronAPI||!window.electronAPI.getProfiles)return; window.electronAPI.getProfiles().then(function(d){var p=d.profiles.find(function(x){return x.name.toLowerCase()===a.toLowerCase();});if(p&&p.id!==d.activeProfile&&window.electronAPI.switchProfile)window.electronAPI.switchProfile(p.id);}); }},
  { name: 'calc', desc: 'Evaluate expression', cat: 'misc', args: 'expression', fn: function(a) { if(!a)return; var r=_tryMath(a); if(r!==null){navigator.clipboard.writeText(String(r)).catch(function(){}); customAlert(a+' = '+r);}else{customAlert('Could not evaluate: '+a);} }},
  { name: 'search', desc: 'Search the web', cat: 'nav', args: 'query', fn: function(a) { if(a)navigateTo(a); }},
  { name: 'dark', desc: 'Force dark mode', cat: 'misc', args: '', fn: function() { toggleForceDark(); }},
  { name: 'findall', desc: 'Search all tabs', cat: 'misc', args: '', fn: function() { toggleFindAll(); }},
  { name: 'autoscroll', desc: 'Page autoscroll', cat: 'misc', args: '', fn: function() { if (_autoscrollActive) stopAutoscroll(); else startAutoscroll(); }},
  { name: 'equalizer', desc: 'Audio equalizer', cat: 'misc', args: '', fn: function() { toggleEqPanel(); }},
  { name: 'hover-translate', desc: 'Hover translate (on/off)', cat: 'misc', args: '', fn: function() { toggleHoverTranslate(); }},
  { name: 'custom', desc: 'Manage custom commands', cat: 'cfg', args: 'add/remove/list', fn: function(a, qcInput) {
    if (!a) { qcInput.value = ':custom '; renderQcList(':custom '); qcInput.focus(); return; }
    var parts = a.split(/\s+/);
    var sub = (parts[0] || '').toLowerCase();
    if (sub === 'list') {
      if (_qcCustomCommands.length === 0) { customAlert('No custom commands'); return; }
      var msg = _qcCustomCommands.map(function(c) { return ':' + c.name + ' — ' + c.desc; }).join('\n');
      customAlert(msg);
    } else if (sub === 'add') {
      var name = parts[1];
      if (!name) { customAlert('Format: :custom add <name> <url|js:code>'); return; }
      var rest = parts.slice(2).join(' ');
      if (!rest) { customAlert('Specify a URL or js:code'); return; }
      var isJs = rest.indexOf('js:') === 0;
      var existing = _qcCustomCommands.findIndex(function(c) { return c.name === name; });
      var cmdObj = { name: name, desc: (isJs ? 'JS: ' + rest.substring(3, 50) : 'URL: ' + rest), type: isJs ? 'js' : 'url', value: isJs ? rest.substring(3) : rest };
      if (existing >= 0) _qcCustomCommands[existing] = cmdObj; else _qcCustomCommands.push(cmdObj);
      _qcSaveCustom();
      customAlert('Command :' + name + ' ' + (existing >= 0 ? 'updated' : 'added'));
    } else if (sub === 'remove') {
      var rname = parts[1];
      if (!rname) { customAlert('Format: :custom remove <name>'); return; }
      var idx = _qcCustomCommands.findIndex(function(c) { return c.name === rname; });
      if (idx >= 0) { _qcCustomCommands.splice(idx, 1); _qcSaveCustom(); customAlert('Command :' + rname + ' removed'); }
      else { customAlert('Command :' + rname + ' not found'); }
    }
  }},
  { name: 'alias', desc: 'Manage command aliases', cat: 'cfg', args: 'add/remove/list', fn: function(a, qcInput) {
    if (!a) { qcInput.value = ':alias '; renderQcList(':alias '); qcInput.focus(); return; }
    var parts = a.split(/\s+/);
    var sub = (parts[0] || '').toLowerCase();
    if (sub === 'list') {
      var msg = Object.keys(_qcAliases).filter(function(k) { return _qcAliases[k]; }).map(function(k) { return ':' + k + ' → :' + _qcAliases[k]; }).join('\n');
      customAlert(msg || 'No aliases');
    } else if (sub === 'add') {
      var alias = parts[1]; var target = parts[2];
      if (!alias || !target) { customAlert('Format: :alias add <alias> <command>'); return; }
      _qcAliases[alias] = target;
      _qcSaveAliases();
      customAlert('Alias :' + alias + ' → :' + target + ' added');
    } else if (sub === 'remove') {
      var ralias = parts[1];
      if (!ralias) { customAlert('Format: :alias remove <alias>'); return; }
      if (_qcAliases[ralias]) { delete _qcAliases[ralias]; _qcSaveAliases(); customAlert('Alias :' + ralias + ' removed'); }
      else { customAlert('Alias :' + ralias + ' not found'); }
    }
  }},
  { name: 'emoji', desc: 'Search and insert emoji', cat: 'misc', args: 'query', keepOpen: true, fn: function(a, qcInput) { _qcEmojiMode = true; if (a) { qcInput.value = ':emoji ' + a; renderQcList(':emoji ' + a); qcInput.focus(); } else { qcInput.value = ':emoji '; renderQcList(':emoji '); qcInput.focus(); } }},
  { name: 'en', desc: 'Translate text to English', cat: 'misc', args: 'text', keepOpen: true, fn: function(a, qcInput) {
    if (!a) return;
    var textToTranslate = a;
    var tab = getActiveTab();
    if (tab && canExecInWebview(tab.webview)) {
      tab.webview.executeJavaScript('window.getSelection().toString()').then(function(sel) {
        if (sel) textToTranslate = sel;
        doTranslate(textToTranslate, 'auto', 'en', qcInput);
      }).catch(function() { doTranslate(textToTranslate, 'auto', 'en', qcInput); });
    } else { doTranslate(textToTranslate, 'auto', 'en', qcInput); }
  }},
  { name: 'ru', desc: 'Translate text to Russian', cat: 'misc', args: 'text', keepOpen: true, fn: function(a, qcInput) {
    if (!a) return;
    var textToTranslate = a;
    var tab = getActiveTab();
    if (tab && canExecInWebview(tab.webview)) {
      tab.webview.executeJavaScript('window.getSelection().toString()').then(function(sel) {
        if (sel) textToTranslate = sel;
        doTranslate(textToTranslate, 'auto', 'ru', qcInput);
      }).catch(function() { doTranslate(textToTranslate, 'auto', 'ru', qcInput); });
    } else { doTranslate(textToTranslate, 'auto', 'ru', qcInput); }
  }},
  { name: 'widget', desc: 'Widget mode (mini panel)', cat: 'misc', args: '', fn: function() { toggleQcWidget(); }},
  { name: 'settings', desc: 'Open settings section', cat: 'cfg', args: 'section', fn: function(a) {
    var sections = ['search-engine','startup','scripts','customization','passwords','permissions','proxy','system-integration','profiles','blocker','security','optimization','paths','backup','hotkeys'];
    var target = a && sections.indexOf(a) >= 0 ? a : '';
    createNewTab('Settings.html' + (target ? '#' + target : ''));
  }},
  { name: 'zapper', desc: 'Hide element on page (Element Zapper)', cat: 'misc', args: '', fn: function() {
    var t = getActiveTab(); if (t && canExecInWebview(t.webview)) t.webview.executeJavaScript('if(window.electronAPI&&window.electronAPI.startElementPicker){window.electronAPI.startElementPicker();return 1}return 0').catch(function() {});
  }},
  { name: 'sleep', desc: 'Put active tab to sleep (except last)', cat: 'tab', args: '', fn: function() {
    var t = getActiveTab();
    if (t && tabs.length > 1 && t.webview && t.isReady && !t._isSleeping) {
      var u = ''; try { u = t.webview.getURL ? t.webview.getURL() : t.webview.src; } catch(e) {}
      if (u && u !== 'about:blank' && !isDomainNoSleep(u)) {
        _maybeClearSWBeforeSleep(t);
        t._sleepUrl = u; t.pendingUrl = u; t.lastUrl = null;
        try { t.webview.loadURL('about:blank'); } catch(e) {}
        t._isSleeping = true;
        var el = document.querySelector('[data-tab-id="' + t.id + '"]');
        if (el) { el.classList.add('tab-sleeping'); var f = el.querySelector('.tab-favicon, .tab-favicon-placeholder'); if (f) f.classList.add('tab-sleeping-favicon'); }
      }
    }
  }},
  { name: 'sleep-others', desc: 'Put all tabs to sleep except active', cat: 'tab', args: '', fn: function() {
    var n = sleepAllTabsExceptActive();
    customAlert('Tabs put to sleep: ' + n);
  }},
  { name: 'tab-dedup', desc: 'Find duplicate tabs', cat: 'tab', args: '', fn: function() {
    var seen = {}; var dups = [];
    tabs.forEach(function(t) {
      var u = ''; try { u = t.webview && t.webview.getURL ? t.webview.getURL() : ''; } catch(e) {}
      if (!u) return;
      if (seen[u]) dups.push(t.id); else seen[u] = u;
    });
    if (dups.length === 0) { customAlert('No duplicates found'); return; }
    customAlert('Found duplicates: ' + dups.length + '. Closing...');
    dups.forEach(function(id) { if (tabs.length > 1) closeTab(id); });
  }},
  { name: 'tab-list', desc: 'List all tabs', cat: 'tab', args: '', keepOpen: true, fn: function(a, qcInput) {
    var html = tabs.map(function(t, i) { return (i+1) + '. ' + (t.title || 'Untitled'); }).join('\n');
    customAlert('Open tabs: ' + tabs.length + '\n\n' + html);
  }},
  { name: 'close-timer', desc: 'Close timer for active tab (minutes)', cat: 'tab', args: 'minutes', fn: function(a) {
    var m = parseInt(a); if (isNaN(m) || m <= 0) { customAlert('Specify minutes, e.g. :close-timer 15'); return; }
    setTabCloseAfter(activeTabId, m);
    customAlert('Tab will close in ' + m + ' min');
  }},
  { name: 'session-guard', desc: 'Session Guard (duplicate detection) on/off', cat: 'cfg', args: 'on/off', fn: function(a) {
    var enable = a !== 'off';
    _sessionGuardCfg.enabled = enable;
    if (window.electronAPI && window.electronAPI.saveCustomizationSettings) {
      window.electronAPI.saveCustomizationSettings({ sessionGuard: { enabled: enable, scope: _sessionGuardCfg.scope, action: _sessionGuardCfg.action } });
    }
    customAlert('Session Guard: ' + (enable ? 'enabled' : 'disabled'));
  }},
  // ============ VIM COMMANDS (via Quick Commands) ============
  // All main vim-mode commands live here, in the QC palette. Inside the page
  // command line there is NONE — this is done for unified UI (autocomplete, history,
  // help). Only window.__spzVimExec(action, arg) is injected into the page,
  // called via tab.webview.executeJavaScript.
  { name: 'vim', desc: 'List of all vim commands', cat: 'vim', args: '', keepOpen: true, fn: function(a, qcInput) {
    if (qcInput) { qcInput.value=':vim-'; _qcRenderFiltered('vim'); qcInput.focus(); }
  }},
  { name: 'vim-on', desc: 'Enable vim mode (if disabled)', cat: 'vim', args: '', fn: function() {
    if (window.electronAPI && window.electronAPI.getVimSettings && window.electronAPI.setVimSettings) {
      window.electronAPI.getVimSettings().then(function(v){
        if (v && v.enabled) { if (typeof _showToast==='function') _showToast('Vim is already enabled', 'vim', null, 'info'); return; }
        window.electronAPI.setVimSettings({ enabled: true, keys: v && v.keys });
      });
    }
  }},
  { name: 'vim-off', desc: 'Turn off vim mode', cat: 'vim', args: '', fn: function() {
    if (window.electronAPI && window.electronAPI.getVimSettings && window.electronAPI.setVimSettings) {
      window.electronAPI.getVimSettings().then(function(v){
        window.electronAPI.setVimSettings({ enabled: false, keys: v && v.keys });
      });
    }
  }},
  { name: 'vim-toggle', desc: 'Toggle vim mode', cat: 'vim', args: '', fn: function() {
    if (window.electronAPI && window.electronAPI.getVimSettings && window.electronAPI.setVimSettings) {
      window.electronAPI.getVimSettings().then(function(v){
        window.electronAPI.setVimSettings({ enabled: !v.enabled, keys: v && v.keys });
      });
    }
  }},
  { name: 'vim-help', desc: 'Open vim help page', cat: 'vim', args: '', fn: function() {
    var lines = [
      'Vim controls — command list',
      '',
      'MODES (status bar bottom right):',
      '  NORMAL — default mode, all keys work',
      '  INSERT (i) — normal typing; Esc — exit',
      '  VISUAL (v) / VISUAL LINE (V) — selection; y — copy',
      '  HINT (f) — click link by letters; F — in new tab',
      '',
      'NAVIGATION:',
      '  j k h l — down/up/left/right',
      '  d u — half page down/up    Ctrl+d Ctrl+u — full screen',
      '  gg G — top / bottom of page',
      '  0 $ — left / right edge',
      '  / — search page (find bar)   n N — next / previous',
      '  [[ ]] — previous / next page',
      '',
      'EDITING:',
      '  yy — copy URL   p — open URL from clipboard',
      '  m{letter} — set mark   \'{letter} — go to mark',
      '  In VISUAL: j k h l — extend selection, y — copy',
      '',
      'BROWSER:',
      '  r R — reload / reload no cache   s — stop loading',
      '  t x X — new / close / restore tab',
      '  J K — next / previous tab',
      '  o — focus address bar   H L — back / forward',
      '  + - zz — zoom in / out / reset',
      '',
      'COMMANDS (:):  type : in Quick Commands and pick from the list.',
      'All keys are customizable: Settings → Hotkeys → Vim controls.'
    ];
    customAlert(lines.join('\n'));
  }},
  { name: 'vim-keys', desc: 'Show current vim keys', cat: 'vim', args: '', fn: function() {
    if (!window.electronAPI || !window.electronAPI.getVimSettings) return;
    window.electronAPI.getVimSettings().then(function(v){
      var keys = (v && v.keys) || {};
      var lines = ['Vim keys (enabled=' + (v && v.enabled ? 'ON' : 'OFF') + '):', ''];
      Object.keys(keys).forEach(function(action){
        lines.push('  ' + (keys[action] || '—').padEnd(10) + ' → ' + action);
      });
      customAlert(lines.join('\n'));
    });
  }},
  { name: 'vim-hint', desc: 'Vim: click link by letters', cat: 'vim', args: '', fn: function() { _vimExecInActive('hint'); }},
  { name: 'vim-hint-tab', desc: 'Vim: open link in new tab', cat: 'vim', args: '', fn: function() { _vimExecInActive('hintTab'); }},
  { name: 'vim-insert', desc: 'Vim: enter INSERT mode', cat: 'vim', args: '', fn: function() { _vimExecInActive('insert'); }},
  { name: 'vim-visual', desc: 'Vim: visual mode', cat: 'vim', args: '', fn: function() { _vimExecInActive('visual'); }},
  { name: 'vim-visual-line', desc: 'Vim: visual mode (linewise)', cat: 'vim', args: '', fn: function() { _vimExecInActive('visualLine'); }},
  { name: 'vim-normal', desc: 'Vim: return to NORMAL mode', cat: 'vim', args: '', fn: function() { _vimExecInActive('normal'); }},
  { name: 'vim-yank', desc: 'Vim: copy current page URL', cat: 'vim', args: '', fn: function() { _vimExecInActive('yankUrl'); }},
  { name: 'vim-top', desc: 'Vim: top of page', cat: 'vim', args: '', fn: function() { _vimExecInActive('scrollTop'); }},
  { name: 'vim-bottom', desc: 'Vim: bottom of page', cat: 'vim', args: '', fn: function() { _vimExecInActive('scrollBottom'); }},
  { name: 'vim-prev-page', desc: 'Vim: previous page', cat: 'vim', args: '', fn: function() { _vimExecInActive('goRelPrev'); }},
  { name: 'vim-next-page', desc: 'Vim: next page', cat: 'vim', args: '', fn: function() { _vimExecInActive('goRelNext'); }},
  { name: 'vim-mark', desc: 'Vim: set mark (letter a-z)', cat: 'vim', args: 'letter', fn: function(a) {
    if (!a) { if (typeof _showToast==='function') _showToast('Specify a letter: :vim-mark a', 'vim', null, 'warn'); return; }
    _vimExecInActive('markSet', a.trim()[0] || 'a');
  }},
  { name: 'vim-jump', desc: 'Vim: jump to mark (letter a-z)', cat: 'vim', args: 'letter', fn: function(a) {
    if (!a) { if (typeof _showToast==='function') _showToast('Specify a letter: :vim-jump a', 'vim', null, 'warn'); return; }
    _vimExecInActive('markJump', a.trim()[0] || 'a');
  }},
];

function getActiveTab() {
  return tabs.find(function(t) { return t.id === activeTabId; });
}

function toggleQuickCommands() {
  var overlay = document.getElementById('qcOverlay');
  var input = document.getElementById('qcInput');
  if (!overlay) return;
  if (_qcVisible) {
    var container = overlay.querySelector('.qc-container');
    if (container) {
      container.style.animation = 'qcOut 0.15s cubic-bezier(0.4, 0, 1, 1) forwards';
      container.addEventListener('animationend', function handler() {
        container.removeEventListener('animationend', handler);
        overlay.classList.remove('visible');
        container.style.animation = '';
        _qcVisible = false;
      });
    } else {
      overlay.classList.remove('visible');
      _qcVisible = false;
    }
  } else {
    overlay.classList.add('visible');
    _qcVisible = true;
    input.value = '';
    _qcActiveIdx = 0;
    _qcHelpPage = 0;
    _qcPreviewData = null;
    renderQcList('');
    setTimeout(function() { input.focus(); }, 50);
  }
}

function _qcExecChain(cmdPart) {
  var chainParts = cmdPart.split('|');
  chainParts.forEach(function(part) {
    var trimmed = part.trim();
    if (!trimmed) return;
    var cName = trimmed.split(/\s+/)[0].toLowerCase();
    var cArg = trimmed.indexOf(' ') >= 0 ? trimmed.substring(trimmed.indexOf(' ') + 1) : '';
    cName = _resolveAlias(cName);
    var cmd = null;
    for (var i = 0; i < _qcCommands.length; i++) {
      if (_qcCommands[i].name === cName) { cmd = _qcCommands[i]; break; }
    }
    if (!cmd) {
      var custom = null;
      for (var j = 0; j < _qcCustomCommands.length; j++) {
        if (_qcCustomCommands[j].name === cName) { custom = _qcCustomCommands[j]; break; }
      }
      if (custom) {
        if (custom.type === 'js') {
          var t = getActiveTab();
          if (t && canExecInWebview(t.webview)) t.webview.executeJavaScript(custom.value).catch(function() {});
        } else {
          navigateTo(custom.value);
        }
      }
      return;
    }
    cmd.fn(cArg, { value: '' });
  });
}

function _qcGeneratePreview(cmdName, cmdArg) {
  _qcPreviewData = null;
  var previewEl = document.getElementById('qcPreview');
  if (!previewEl) return;

  var resolvedName = _resolveAlias(cmdName);
  var cmd = null;
  for (var i = 0; i < _qcCommands.length; i++) {
    if (_qcCommands[i].name === resolvedName) { cmd = _qcCommands[i]; break; }
  }

  if (!cmd) {
    var custom = null;
    for (var j = 0; j < _qcCustomCommands.length; j++) {
      if (_qcCustomCommands[j].name === resolvedName) { custom = _qcCustomCommands[j]; break; }
    }
    if (custom) {
      _qcPreviewData = { type: 'custom', cmd: custom };
      previewEl.innerHTML = '<div class="qc-preview-title">' + escapeHtmlSimple(custom.name) + '</div>' +
        '<div class="qc-preview-desc">' + escapeHtmlSimple(custom.desc) + '</div>' +
        '<div class="qc-preview-type">Type: ' + (custom.type === 'js' ? 'JavaScript' : 'URL') + '</div>';
      previewEl.classList.add('visible');
    } else {
      previewEl.classList.remove('visible');
    }
    return;
  }

  var html = '';
  if (resolvedName === 'calc' && cmdArg) {
    var r = _tryMath(cmdArg);
    if (r !== null) {
      html = '<div class="qc-preview-title">Result</div><div class="qc-preview-result">' + escapeHtmlSimple(String(r)) + '</div>';
      _qcPreviewData = { type: 'calc', value: r };
    }
  } else if (resolvedName === 'open' && cmdArg) {
    html = '<div class="qc-preview-title">Open URL</div><div class="qc-preview-url">' + escapeHtmlSimple(cmdArg) + '</div>';
  } else if (resolvedName === 'zoom' && cmdArg) {
    var zv = parseInt(cmdArg);
    if (!isNaN(zv)) html = '<div class="qc-preview-title">Zoom</div><div class="qc-preview-result">' + zv + '%</div>';
  } else if (resolvedName === 'search' && cmdArg) {
    html = '<div class="qc-preview-title">Search</div><div class="qc-preview-url">' + escapeHtmlSimple(cmdArg) + '</div>';
  } else if (resolvedName === 'alias') {
    var aliasList = Object.keys(_qcAliases).filter(function(k) { return _qcAliases[k]; }).map(function(k) { return ':' + k + ' → :' + _qcAliases[k]; });
    html = '<div class="qc-preview-title">Aliases</div><div class="qc-preview-aliases">' + (aliasList.length ? aliasList.map(escapeHtmlSimple).join('<br>') : 'No aliases') + '</div>';
  } else {
    var catNames = { nav: 'Navigation', tab: 'Tabs', bm: 'Bookmarks', hist: 'History', cfg: 'Settings', link: 'Page', dl: 'Downloads', misc: 'Misc' };
    html = '<div class="qc-preview-title">' + escapeHtmlSimple(cmd.name) + '</div>' +
      '<div class="qc-preview-desc">' + escapeHtmlSimple(cmd.desc) + '</div>' +
      '<div class="qc-preview-cat">Category: ' + (catNames[cmd.cat] || cmd.cat) + '</div>';
    var aliasFor = Object.keys(_qcAliases).filter(function(k) { return _qcAliases[k] === cmd.name; });
    if (aliasFor.length) html += '<div class="qc-preview-alias-for">Alias: :' + aliasFor.join(', :') + '</div>';
  }

  if (html) {
    previewEl.innerHTML = html;
    previewEl.classList.add('visible');
  } else {
    previewEl.classList.remove('visible');
  }
}

function _tryMath(expr) {
  if (!expr || expr.length < 1) return null;
  if (!/^[0-9\s\+\-\*\/\.\(\)\^%pipi,e\s]+$/.test(expr.replace(/sqrt|sin|cos|tan|log|ln|abs|ceil|floor|round|pow|min|max|PI|E/gi, ''))) return null;
  if (!/\d/.test(expr)) return null;
  if (/^[0-9\s\.]+$/.test(expr.trim()) && expr.trim().length < 3) return null;
  try {
    var safe = expr
      .replace(/\^/g, '**')
      .replace(/π/g, 'Math.PI')
      .replace(/\bpi\b/gi, 'Math.PI')
      .replace(/\be\b/g, 'Math.E')
      .replace(/\bsqrt\b/gi, 'Math.sqrt')
      .replace(/\bsin\b/gi, 'Math.sin')
      .replace(/\bcos\b/gi, 'Math.cos')
      .replace(/\btan\b/gi, 'Math.tan')
      .replace(/\blog\b/gi, 'Math.log10')
      .replace(/\bln\b/gi, 'Math.log')
      .replace(/\babs\b/gi, 'Math.abs')
      .replace(/\bceil\b/gi, 'Math.ceil')
      .replace(/\bfloor\b/gi, 'Math.floor')
      .replace(/\bround\b/gi, 'Math.round')
      .replace(/\bpow\b/gi, 'Math.pow')
      .replace(/\bmin\b/gi, 'Math.min')
      .replace(/\bmax\b/gi, 'Math.max');
    var result = Function('"use strict"; return (' + safe + ')')();
    if (typeof result === 'number' && isFinite(result)) {
      var rounded = Math.round(result * 1e12) / 1e12;
      return rounded;
    }
  } catch(e) {}
  return null;
}

function renderQcList(query) {
  var list = document.getElementById('qcList');
  if (!list) return;
  _qcItems = [];
  var q = (query || '').trim();
  var qcInput = document.getElementById('qcInput');

  function add(icon, title, sub, action, shortcut, preview) {
    _qcItems.push({ icon: icon, title: title, sub: sub, action: action, shortcut: shortcut || '', preview: preview || '' });
  }

  if (q.charAt(0) === ':') {
    var cmdPart = q.substring(1).trim();

    if (cmdPart.indexOf('|') > 0) {
      var chainPreview = cmdPart.split('|').map(function(p) { return ':' + p.trim(); }).join(' → ');
      add('\u26A1', 'Run chain: ' + chainPreview, 'Multiple commands in sequence', function() { _qcExecChain(cmdPart); toggleQuickCommands(); }, '', chainPreview);
    } else if (cmdPart.indexOf('emoji') === 0 || cmdPart.indexOf('emoji ') === 0) {
      var emojiQ = cmdPart.indexOf(' ') >= 0 ? cmdPart.substring(6).trim().toLowerCase() : '';
      _qcEmojiMode = true;
      if (emojiQ) {
        var emojiMatches = _qcEmojiData.filter(function(item) {
          return item.n.some(function(tag) { return tag.indexOf(emojiQ) >= 0; });
        });
        emojiMatches.forEach(function(item) {
          add(item.e, item.e + '  ' + item.n.slice(0, 3).join(', '), 'Click to copy', function() {
            navigator.clipboard.writeText(item.e).catch(function() {});
            toggleQuickCommands();
          });
        });
        if (emojiMatches.length === 0) {
          add('\uD83D\uDE10', 'Nothing found', 'Try another query', function() {});
        }
      } else {
        _qcEmojiData.slice(0, _qcHelpPageSize).forEach(function(item) {
          add(item.e, item.e + '  ' + item.n.slice(0, 3).join(', '), 'Click to copy', function() {
            navigator.clipboard.writeText(item.e).catch(function() {});
            toggleQuickCommands();
          });
        });
        if (_qcEmojiData.length > _qcHelpPageSize) {
          add('\u25B6', 'More emoji...', 'Show all', function() {
            _qcActionHandledClose = true; qcInput.value = ':emoji a'; renderQcList(':emoji a'); qcInput.focus();
          });
        }
      }
    } else {
      var cmdName = cmdPart.split(/\s+/)[0].toLowerCase();
      var cmdArg = cmdPart.indexOf(' ') >= 0 ? cmdPart.substring(cmdPart.indexOf(' ') + 1) : '';

      var resolvedName = _resolveAlias(cmdName);
      var isAlias = resolvedName !== cmdName;

      var allCmds = _qcCommands.concat(_qcCustomCommands.map(function(c) {
        return { name: c.name, desc: c.desc, cat: 'custom', args: c.type === 'js' ? 'js' : 'URL', fn: function(a) {
          if (c.type === 'js') { var t = getActiveTab(); if (t && canExecInWebview(t.webview)) t.webview.executeJavaScript(c.value).catch(function() {}); }
          else { navigateTo(c.value); }
        }};
      }));

      if (cmdName === '' && cmdPart === '') {
        var catIcons = { nav: '\uD83D\uDCC1', tab: '\uD83D\uDCE6', bm: '\u2B50', hist: '\uD83D\uDDD3\uFE0F', cfg: '\u2699\uFE0F', link: '\uD83D\uDD17', dl: '\uD83D\uDCE5', misc: '\u2728', custom: '\uD83C\uDFA8' };
        var catNames = { nav: 'Navigation', tab: 'Tabs', bm: 'Bookmarks', hist: 'History', cfg: 'Settings', link: 'Page', dl: 'Downloads', misc: 'Misc', custom: 'Custom' };
        var catOrder = ['nav', 'tab', 'bm', 'hist', 'cfg', 'link', 'dl', 'custom', 'misc'];

        var grouped = {};
        allCmds.forEach(function(cmd) {
          var cat = cmd.cat || 'misc';
          if (!grouped[cat]) grouped[cat] = [];
          grouped[cat].push(cmd);
        });

        var allFlat = [];
        catOrder.forEach(function(cat) {
          if (grouped[cat]) allFlat = allFlat.concat(grouped[cat]);
        });
        Object.keys(grouped).forEach(function(cat) {
          if (catOrder.indexOf(cat) < 0) allFlat = allFlat.concat(grouped[cat]);
        });

        var totalPages = Math.max(1, Math.ceil(allFlat.length / _qcHelpPageSize));
        if (_qcHelpPage >= totalPages) _qcHelpPage = totalPages - 1;
        var startIdx = _qcHelpPage * _qcHelpPageSize;
        var pageItems = allFlat.slice(startIdx, startIdx + _qcHelpPageSize);

        add('\uD83D\uDCD6', 'help (' + (_qcHelpPage + 1) + '/' + totalPages + ')', 'Page ' + (_qcHelpPage + 1) + ' of ' + totalPages + ' · Total commands: ' + allFlat.length, function() {});

        var currentCat = null;
        pageItems.forEach(function(cmd) {
          if (cmd.cat !== currentCat) {
            currentCat = cmd.cat;
            add('', catNames[currentCat] || currentCat, '', function() {}, '', '');
          }
          add(catIcons[cmd.cat] || '\u2318', ':' + cmd.name + (cmd.args ? ' [' + cmd.args + ']' : ''), cmd.desc, function() {
            if (cmd.args) { qcInput.value = ':' + cmd.name + ' '; renderQcList(':' + cmd.name + ' '); qcInput.focus(); }
            else { cmd.fn('', qcInput); _qcActionHandledClose = true; if (!cmd.keepOpen) toggleQuickCommands(); }
          });
        });

        if (totalPages > 1) {
          var navHtml = '';
          if (_qcHelpPage > 0) {
            add('\u25C0', '\u2190 Back', 'Page ' + _qcHelpPage + ' of ' + totalPages, function() { _qcHelpPage--; renderQcList(':'); });
          }
          if (_qcHelpPage < totalPages - 1) {
            add('\u25B6', '\u2192 Next', 'Page ' + (_qcHelpPage + 2) + ' of ' + totalPages, function() { _qcHelpPage++; renderQcList(':'); });
          }
        }
      } else {
        var exactMatch = null;
        var matches = [];
        allCmds.forEach(function(cmd) {
          if (cmd.name === resolvedName || cmd.name === cmdName) exactMatch = cmd;
          if (cmd.name.indexOf(cmdName) === 0 || cmd.name.indexOf(resolvedName) === 0) {
            if (matches.indexOf(cmd) < 0) matches.push(cmd);
          }
        });

        if (isAlias) {
          var aliasMatch = null;
          allCmds.forEach(function(cmd) { if (cmd.name === resolvedName) aliasMatch = cmd; });
          if (aliasMatch && matches.indexOf(aliasMatch) < 0) matches.unshift(aliasMatch);
          if (!exactMatch && aliasMatch) exactMatch = aliasMatch;
        }

        if (exactMatch) {
          if (exactMatch.args && !cmdArg) {
            add('\u2318', ':' + exactMatch.name + ' [' + exactMatch.args + ']' + (isAlias ? ' (:' + cmdName + ')' : ''), exactMatch.desc, function() { qcInput.value = ':' + exactMatch.name + ' '; renderQcList(':' + exactMatch.name + ' '); qcInput.focus(); });
            _qcGeneratePreview(exactMatch.name, '');
          } else {
            var previewText = exactMatch.desc + (cmdArg ? ' \u2192 ' + cmdArg : '');
            add('\u25B6', ':' + exactMatch.name + (cmdArg ? ' ' + cmdArg : '') + (isAlias ? ' (:' + cmdName + ')' : ''), previewText, function() { exactMatch.fn(cmdArg, qcInput); _qcActionHandledClose = true; if (!exactMatch.keepOpen) toggleQuickCommands(); });
            _qcGeneratePreview(exactMatch.name, cmdArg);
          }
        }

        if (!exactMatch || (!exactMatch.args && matches.length > 1)) {
          matches.forEach(function(cmd) {
            if (cmd === exactMatch && !cmd.args) return;
            add('\u2318', ':' + cmd.name + (cmd.args ? ' [' + cmd.args + ']' : ''), cmd.desc, function() {
              if (cmd.args) { qcInput.value = ':' + cmd.name + ' '; renderQcList(':' + cmd.name + ' '); qcInput.focus(); }
              else { cmd.fn('', qcInput); _qcActionHandledClose = true; if (!cmd.keepOpen) toggleQuickCommands(); }
            });
          });
        }

        if (!exactMatch && cmdName.indexOf('http') === 0) {
          add('\uD83C\uDF10', 'Open ' + cmdName, cmdName, function() { navigateTo(cmdName); toggleQuickCommands(); });
        }
      }
    }
  } else {
    var qLower = q.toLowerCase();

    var mathResult = _tryMath(q);
    if (mathResult !== null) {
      add('\uD83E\uDDEE', q + ' = ' + mathResult, 'Calculator — Enter to copy', function() {
        navigator.clipboard.writeText(String(mathResult)).catch(function() {});
        toggleQuickCommands();
      }, '', '= ' + mathResult);
    }

    if (/^[\?\/]/.test(q) || q.length >= 2) {
      var searchQ = q.replace(/^[\?\/]\s*/, '');
      if (searchQ.length >= 2) {
        var seName = 'Google';
        add('\uD83D\uDD0D', 'Search "' + searchQ + '»', seName, function() { navigateTo(searchQ); toggleQuickCommands(); });
      }
    }

    function addSearch(icon, title, sub, action, shortcut, preview) {
      if (q) {
        var haystack = (title + ' ' + sub + ' ' + (shortcut || '')).toLowerCase();
        if (haystack.indexOf(qLower) === -1) return;
      }
      _qcItems.push({ icon: icon, title: title, sub: sub, action: action, shortcut: shortcut || '', preview: preview || '' });
    }

    tabs.forEach(function(t) {
      var url = '';
      try { url = t.webview.getURL ? t.webview.getURL() : (t.webview.src || ''); } catch(e) { url = t.webview.src || ''; }
      if (url) {
        addSearch('\uD83C\uDF10', t.title || url, url.length > 60 ? url.substring(0, 60) + '...' : url, function() { setActiveTab(t.id); });
      }
    });

    if (closedTabsHistory.length > 0) {
      closedTabsHistory.slice(0, 10).forEach(function(c, i) {
        addSearch('\u21A9', c.title || c.url, c.url.length > 60 ? c.url.substring(0, 60) + '...' : c.url, function() { closedTabsHistory.splice(i, 1); createNewTab(c.url); });
      });
    }

    addSearch('\uD83C\uDF10', 'New tab', 'Open blank tab', function() { createNewTab(); }, 'Ctrl+T');
    addSearch('\u2699\uFE0F', 'Settings', 'Open browser settings', function() { createNewTab('Settings.html'); });
    addSearch('\uD83D\uDD0D', 'Find on page', 'Search current page', function() { toggleFindBar(); }, 'Ctrl+F');
    addSearch('\uD83D\uDD0D\uFE0F', 'Search all tabs', 'Find text in all open tabs', function() { toggleFindAll(); }, 'Ctrl+Shift+F');
    addSearch('\uD83D\uDFE3', 'Autoscroll', 'Smooth scroll with speed control', function() { if (_autoscrollActive) stopAutoscroll(); else startAutoscroll(); });
    addSearch('\uD83D\uDCF7', 'Page screenshot', 'Save screenshot of visible area', function() { takeScreenshot(); });
    addSearch('\uD83D\uDD12', 'Adblock: on/off', 'Toggle ad blocker', function() {
      if (window.electronAPI && window.electronAPI.adblockerToggle) window.electronAPI.adblockerToggle();
    });
    addSearch('\uD83D\uDCDD', 'Bookmarks', 'Open bookmark manager', function() { createNewTab('Settings.html#bookmarks'); });
    addSearch('\uD83D\uDCDC', 'Downloads', 'Open downloads', function() { createNewTab('Settings.html#downloads'); });
    addSearch('\uD83D\uDD11', 'Passwords', 'Open password manager', function() { createNewTab('Settings.html#passwords'); });
    addSearch('\uD83C\uDF10', 'History', 'Open history', function() { createNewTab('Settings.html#history'); });
    addSearch('\uD83D\uDFE2', 'PiP (Picture in Picture)', 'Toggle PiP for video', function() {
      var tab = tabs.find(function(t) { return t.id === activeTabId; });
      if (tab && canExecInWebview(tab.webview)) {
        tab.webview.executeJavaScript('(function(){var v=document.querySelector("video");if(!v)return"no-video";if(document.pictureInPictureElement){document.exitPictureInPicture().catch(function(){});}else{v.requestPictureInPicture().catch(function(){});}return 0})()').catch(function() {});
      }
    }, 'Alt+P');
    addSearch('\uD83D\uDCBB', 'Developer tools', 'Open DevTools', function() {
      var tab = tabs.find(function(t) { return t.id === activeTabId; });
      if (tab && tab.webview) { try { tab.webview.toggleDevTools(); } catch(e) {} }
    }, 'F12');
    addSearch('\uD83C\uDF10', 'Fullscreen', 'Toggle fullscreen mode', function() {
      if (window.electronAPI && window.electronAPI.toggleWindowFullscreen) window.electronAPI.toggleWindowFullscreen();
    }, 'F11');
  }

  if (_qcActiveIdx >= _qcItems.length) _qcActiveIdx = 0;

  if (_qcItems.length === 0) {
    list.innerHTML = '<div class="qc-empty">Nothing found</div>';
    return;
  }

  var html = '';
  _qcItems.forEach(function(item, i) {
    if (!item.icon && !item.title) return;
    if (!item.icon && item.title && !item.sub && !item.action) {
      html += '<div class="qc-category-header">' + escapeHtmlSimple(item.title) + '</div>';
      return;
    }
    var cls = i === _qcActiveIdx ? 'qc-item active' : 'qc-item';
    html += '<div class="' + cls + '" data-idx="' + i + '">' +
      '<div class="qc-item-icon">' + _icon(item.icon) + '</div>' +
      '<div class="qc-item-text"><div class="qc-item-title">' + escapeHtmlSimple(item.title) + '</div>' +
      '<div class="qc-item-sub">' + escapeHtmlSimple(item.sub) + '</div></div>' +
      (item.shortcut ? '<div class="qc-item-shortcut">' + item.shortcut + '</div>' : '') +
      '</div>';
  });
  list.innerHTML = html;

  list.querySelectorAll('.qc-item').forEach(function(el) {
    el.addEventListener('click', function() {
      var idx = parseInt(el.getAttribute('data-idx'));
      if (_qcItems[idx]) {
        _qcItems[idx].action();
      }
    });
    el.addEventListener('mouseenter', function() {
      _qcActiveIdx = parseInt(el.getAttribute('data-idx'));
      list.querySelectorAll('.qc-item').forEach(function(e, j) {
        e.classList.toggle('active', j === _qcActiveIdx);
      });
    });
  });
}

(function() {
  var overlay = document.getElementById('qcOverlay');
  var input = document.getElementById('qcInput');
  if (!overlay || !input) return;

  overlay.addEventListener('click', function(e) {
    if (e.target === overlay) toggleQuickCommands();
  });

  input.addEventListener('input', function() {
    _qcActiveIdx = 0;
    renderQcList(input.value);
  });

  input.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      toggleQuickCommands();
      return;
    }
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      if (_qcItems.length > 0) {
        _qcActiveIdx = (_qcActiveIdx + 1) % _qcItems.length;
        renderQcList(input.value);
      }
      return;
    }
    if (e.key === 'ArrowUp') {
      e.preventDefault();
      if (_qcItems.length > 0) {
        _qcActiveIdx = (_qcActiveIdx - 1 + _qcItems.length) % _qcItems.length;
        renderQcList(input.value);
      }
      return;
    }
    if (e.key === 'Enter') {
      e.preventDefault();
      if (_qcItems[_qcActiveIdx]) {
        var inputVal = input.value;
        if (inputVal.charAt(0) === ':' && inputVal.indexOf('|') > 0 && inputVal.substring(1).trim().split('|').every(function(p) { var n = p.trim().split(/\s+/)[0].toLowerCase(); return _qcCommands.some(function(c) { return c.name === _resolveAlias(n); }) || _qcCustomCommands.some(function(c) { return c.name === n; }); })) {
          _qcExecChain(inputVal.substring(1).trim());
          toggleQuickCommands();
        } else {
          _qcActionHandledClose = false;
          _qcItems[_qcActiveIdx].action();
          if (!_qcActionHandledClose) toggleQuickCommands();
        }
      }
      return;
    }
  });
})();

// ============== TAKE SCREENSHOT ==============
function takeScreenshot() {
  var tab = tabs.find(function(t) { return t.id === activeTabId; });
  if (!tab || !tab.webview || !tab.isReady) return;
  try {
    if (tab.webview.isDestroyed && tab.webview.isDestroyed()) return;
    tab.webview.capturePage().then(function(img) {
      if (!img || img.isEmpty()) return;
      if (window.electronAPI && window.electronAPI.saveScreenshot) {
        window.electronAPI.saveScreenshot(img.toDataURL().replace(/^data:image\/png;base64,/, ''));
      }
    }).catch(function() {});
  } catch(e) {}
}

// ============== KEYBOARD SHORTCUTS ==============
(function() {
  function getActiveTab() {
    return tabs.find(function(t) { return t.id === activeTabId; });
  }

  document.addEventListener('keydown', function(e) {
    if (e.key === 'F11') {
      e.preventDefault();
      if (window.electronAPI && window.electronAPI.toggleWindowFullscreen) {
        window.electronAPI.toggleWindowFullscreen();
      }
    }
    if (e.ctrlKey && e.shiftKey && e.key === 'F') {
      e.preventDefault();
      toggleFindAll();
    }
    if (e.altKey && e.key === 'a' && !e.ctrlKey && !e.shiftKey) {
      e.preventDefault();
      if (_autoscrollActive) stopAutoscroll(); else startAutoscroll();
    }
  });

  if (window.electronAPI && window.electronAPI.onShortcutAction) {
    window.electronAPI.onShortcutAction(function(data) {
      var tab = getActiveTab();
      switch (data.action) {
        case 'newTab': createNewTab(); break;
        case 'closeTab': closeTab(activeTabId); break;
        case 'focusUrl': urlInput.focus(); urlInput.select(); break;
        case 'reload':
          if (tab && tab.webview) { try { tab.webview.reload(); } catch(e) {} }
          break;
        case 'stop':
          if (tab && tab.webview) { try { if (tab.webview.isLoading && tab.webview.isLoading()) tab.webview.stop(); } catch(e) {} }
          break;
        case 'nextTab':
        case 'prevTab':
          var idx = tabs.findIndex(function(t) { return t.id === activeTabId; });
          if (idx === -1) return;
          var next = data.action === 'prevTab' ? (idx <= 0 ? tabs.length - 1 : idx - 1) : (idx >= tabs.length - 1 ? 0 : idx + 1);
          setActiveTab(tabs[next].id);
          break;
        case 'tabByIndex':
          var target = data.index === 9 ? tabs.length - 1 : Math.min(data.index - 1, tabs.length - 1);
          if (target >= 0) setActiveTab(tabs[target].id);
          break;
        case 'reopenClosed':
          if (closedTabsHistory.length > 0) { var c = closedTabsHistory.shift(); createNewTab(c.url); }
          break;
        case 'find': toggleFindBar(); break;
        case 'print':
          if (tab && canExecInWebview(tab.webview)) { tab.webview.executeJavaScript('window.print()').catch(function() {}); }
          break;
        case 'savePage':
          if (tab && tab.webview && tab.isReady) {
            var url = '';
            try { url = tab.webview.getURL ? tab.webview.getURL() : tab.webview.src; } catch(e) { url = tab.webview.src; }
            if (url && url.indexOf('file://') !== 0 && window.electronAPI && window.electronAPI.savePageAs) {
              window.electronAPI.savePageAs(url);
            }
          }
          break;
        case 'addBookmark':
          if (tab && tab.webview && tab.isReady) {
            var url = '';
            try { url = tab.webview.getURL ? tab.webview.getURL() : tab.webview.src; } catch(e) { url = tab.webview.src; }
            var title = '';
            try { title = tab.webview.getTitle ? tab.webview.getTitle() : ''; } catch(e) {}
            if (url && url.indexOf('file://') !== 0 && window.electronAPI && window.electronAPI.addBookmark) {
              window.electronAPI.addBookmark({ url: url, title: title || url });
            }
          }
          break;
        case 'goBack':
          if (tab && tab.webview && tab.isReady) { try { if (tab.webview.canGoBack()) tab.webview.goBack(); } catch(e) {} }
          break;
        case 'goForward':
          if (tab && tab.webview && tab.isReady) { try { if (tab.webview.canGoForward()) tab.webview.goForward(); } catch(e) {} }
          break;
        case 'quickCommands': toggleQuickCommands(); break;
        case 'pip':
          if (tab && canExecInWebview(tab.webview)) {
            tab.webview.executeJavaScript(
              '(function(){var v=document.querySelector("video");if(!v)return"no-video";if(document.pictureInPictureElement){document.exitPictureInPicture().catch(function(){});}else{v.requestPictureInPicture().catch(function(){});}})()'
            ).catch(function() {});
          }
          break;
        case 'taskManager':
          openTaskManager();
          break;
      }
    });
  }
})();

// ====== VIM-ACTION: commands from webview (vim mode) ======
// The vim engine (preload-webview.js) sends postMessage → ipc 'vim-action' → here.
// Browser commands: new tab, switch, focus URL, etc.
(function() {
  if (!window.electronAPI || !window.electronAPI.onVimAction) return;
  window.electronAPI.onVimAction(function(payload) {
    // Support for both formats: old string and new {action, arg}
    var action = (payload && typeof payload === 'object') ? payload.action : payload;
    var arg = (payload && typeof payload === 'object') ? payload.arg : undefined;
    var tab = getActiveTab();
    function _newTabUrl(u) {
      if (u) createNewTab(u); else _openHomePage();
    }
    switch (action) {
      case 'reload':
        if (tab && tab.webview) { try { tab.webview.reload(); } catch(e) {} }
        break;
      case 'reloadHard':
        if (tab && tab.webview) { try { tab.webview.reloadIgnoringCache(); } catch(e) {} }
        break;
      case 'stopLoad':
        if (tab && tab.webview) { try { if (tab.webview.isLoading && tab.webview.isLoading()) tab.webview.stop(); } catch(e) {} }
        break;
      case 'newTab':
        _openHomePage();
        break;
      case 'closeTab':
        closeTab(activeTabId);
        break;
      case 'restoreTab':
        if (closedTabsHistory && closedTabsHistory.length > 0) {
          var c = closedTabsHistory.shift();
          createNewTab(c.url);
        }
        break;
      case 'nextTab': {
        var idx = tabs.findIndex(function(t) { return t.id === activeTabId; });
        if (idx !== -1) {
          var next = idx >= tabs.length - 1 ? 0 : idx + 1;
          setActiveTab(tabs[next].id);
        }
        break;
      }
      case 'prevTab': {
        var idx = tabs.findIndex(function(t) { return t.id === activeTabId; });
        if (idx !== -1) {
          var prev = idx <= 0 ? tabs.length - 1 : idx - 1;
          setActiveTab(tabs[prev].id);
        }
        break;
      }
      case 'focusUrl':
        urlInput.focus();
        urlInput.select();
        break;
      case 'focusUrlCurrent':
        urlInput.focus();
        urlInput.select();
        break;
      case 'find':
        toggleFindBar();
        break;
      case 'openUrl':
        // From command mode :open <url>
        _newTabUrl(arg);
        break;
      case 'openUrlCurrent':
        if (arg) navigateTo(arg, activeTabId);
        break;
      case 'searchForward':
        toggleFindBar();
        break;
      case 'back':
        if (tab && tab.webview && tab.isReady) { try { if (tab.webview.canGoBack()) tab.webview.goBack(); } catch(e) {} }
        break;
      case 'forward':
        if (tab && tab.webview && tab.isReady) { try { if (tab.webview.canGoForward()) tab.webview.goForward(); } catch(e) {} }
        break;
      case 'zoomIn':
        if (tab && tab.webview) { try { var z = tab.webview.getZoomFactor ? tab.webview.getZoomFactor() : 1; if (tab.webview.setZoomFactor) tab.webview.setZoomFactor(Math.min(3, z + 0.1)); } catch(e) {} }
        break;
      case 'zoomOut':
        if (tab && tab.webview) { try { var z = tab.webview.getZoomFactor ? tab.webview.getZoomFactor() : 1; if (tab.webview.setZoomFactor) tab.webview.setZoomFactor(Math.max(0.3, z - 0.1)); } catch(e) {} }
        break;
      case 'zoomReset':
        if (tab && tab.webview && tab.webview.setZoomFactor) { try { tab.webview.setZoomFactor(1); } catch(e) {} }
        break;
      case 'pasteUrl':
        if (window.electronAPI && window.electronAPI.readClipboard) {
          window.electronAPI.readClipboard().then(function(text) {
            if (text) _newTabUrl(text.trim());
          });
        }
        break;
      case 'openQC':
        // Vim ':' → open Quick Commands with ':' prefix
        if (typeof toggleQuickCommands === 'function') {
          toggleQuickCommands();
          // If QC is visible — set the prefix
          setTimeout(function() {
            var qi = document.getElementById('qcInput');
            if (qi && !qi.value) { qi.value = (typeof arg === 'string') ? arg : ':'; qi.dispatchEvent(new Event('input')); qi.focus(); }
          }, 30);
        }
        break;
      case 'find':
        if (typeof toggleFindBar === 'function') toggleFindBar();
        break;
      case 'findNext':
        _vimRepeatFind(true);
        break;
      case 'findPrev':
        _vimRepeatFind(false);
        break;
      case 'modeChange':
        // The active webview engine reported its mode (normal/insert/visual/...)
        // Cache it — needed by the chrome handler to avoid intercepting keys in INSERT.
        if (typeof arg === 'string') _vimCache.mode = arg;
        break;
    }
  });
})();

// Repeat find on page (n/N from vim). Uses the text from the find bar
// (if closed — last value). Opens the find bar if needed.
var _vimLastFindText = '';
function _vimRepeatFind(forward) {
  var fi = document.getElementById('findInput');
  var text = fi && fi.value ? fi.value : (_vimLastFindText || '');
  if (!text) {
    if (typeof toggleFindBar === 'function') toggleFindBar();
    return;
  }
  _vimLastFindText = text;
  // Make sure the find bar is open — otherwise stopFindInPage clears the selection
  if (!fi) { if (typeof toggleFindBar === 'function') toggleFindBar(); fi = document.getElementById('findInput'); }
  var tab = getActiveTab();
  if (!tab || !tab.webview || !text) return;
  try { tab.webview.findInPage(text, { forward: !!forward, matchCase: false }); } catch(e) {}
}

// ============== VIM KEYS FROM CHROME → ACTIVE WEBVIEW ==============
// Problem: the vim engine sets a listener on the document INSIDE the page. If
// focus is on the URL bar / toolbar — presses of j, k, f, etc. do not reach
// the page. Solution: catch them in chrome (renderer) and "inject" them into the active
// webview via window.__spzVimInjectKey().
//
// Cache settings and mode to decide synchronously (without waiting for IPC)
// — need to call preventDefault before the key goes to the standard
// chrome handler.
var _vimCache = {
  enabled: false,
  keys: {},                 // action → keystring (as in settings)
  directKeys: {},           // normalizedKeystring → action (for fast check)
  prefixChars: {},          // firstChar → true (for 'g' from 'gg' etc.)
  mode: 'normal'            // current mode of the ACTIVE webview
};

function _vimNormalizeKey(s) {
  if (!s) return '';
  s = String(s).trim();
  if (s === '+' || s === '-') return s;
  var parts = s.split('+').map(function(x){return x.trim();});
  if (parts.length === 1) return parts[0];
  var key = parts[parts.length-1].toLowerCase();
  var mods = parts.slice(0,-1).map(function(m){return m.toLowerCase();}).filter(function(m){return m;});
  mods.sort();
  return mods.length ? (mods.join('+')+'+'+key) : key;
}

function _vimRebuildCache(keys) {
  _vimCache.keys = keys || {};
  _vimCache.directKeys = {};
  _vimCache.prefixChars = {};
  Object.keys(_vimCache.keys).forEach(function(action) {
    var raw = _vimCache.keys[action];
    if (!raw) return;
    var norm = _vimNormalizeKey(raw);
    if (norm) _vimCache.directKeys[norm] = action;
    // Prefix — first character of the key string (ignoring modifiers).
    // E.g. for 'gg' → 'g'; for 'Ctrl+d' → 'ctrl+d' (not a single character,
    // such a prefix is not interesting — only single-char ones are processed).
    if (raw.length > 1 && !/[+]/.test(raw)) {
      var firstChar = raw[0];
      _vimCache.prefixChars[firstChar] = true;
    }
  });
}

function _vimBuildChFromEvent(e) {
  var keyName = e.key || '';
  var hasMod = e.ctrlKey || e.metaKey || e.altKey;
  if (hasMod) {
    var ch = '';
    if (e.ctrlKey || e.metaKey) ch += 'ctrl+';
    if (e.altKey) ch += 'alt+';
    ch += keyName.length === 1 ? keyName.toLowerCase() : keyName.toLowerCase();
    return ch;
  }
  if (e.shiftKey && keyName.length === 1) return keyName;  // 'J','G','H','L'...
  return keyName.length === 1 ? keyName.toLowerCase() : keyName.toLowerCase();
}

function _vimKeyMatchesCache(ch) {
  if (_vimCache.directKeys[ch]) return true;
  // May be the start of a multi-key (gg, yy, [[, ]])
  if (ch.length === 1 && _vimCache.prefixChars[ch]) return true;
  // Two-char prefixes from the same prefixChars: 'yy' starts with 'y' etc.
  // Check: is there anything in directKeys that STARTS with ch
  var found = false;
  Object.keys(_vimCache.directKeys).forEach(function(k) {
    if (k.length > ch.length && k.indexOf(ch) === 0) found = true;
  });
  return found;
}

function _vimIsEditable(el) {
  if (!el) return false;
  var tag = (el.tagName || '').toLowerCase();
  if (tag === 'input' || tag === 'textarea' || tag === 'select') return true;
  if (el.isContentEditable) return true;
  return false;
}

// Check whether a chrome overlay/panel with an input field or its own
// hotkey handler is currently open. Use ONLY reliable JS-state variables
// (boolean) already supported in the code. DOM checks (style.display,
// getBoundingClientRect) are unreliable — many overlays are hidden via
// position:off-screen / opacity / transform, rather than display:none.
function _vimChromeOverlayOpen() {
  // Find bar
  if (typeof _findBarVisible !== 'undefined' && _findBarVisible) return true;
  // Quick Commands
  if (typeof _qcVisible !== 'undefined' && _qcVisible) return true;
  // Find-all
  if (typeof _findallVisible !== 'undefined' && _findallVisible) return true;
  // Screenshot overlay
  if (typeof _ssActive !== 'undefined' && _ssActive) return true;
  // Customize mode
  if (typeof _customizeActive !== 'undefined' && _customizeActive) return true;
  // Autoscroll active (there is an indicator with buttons)
  if (typeof _autoscrollActive !== 'undefined' && _autoscrollActive) return true;
  // Dialog (customAlert/customConfirm/customPrompt) — check via display
  var dlg = document.getElementById('dialogOverlay');
  if (dlg && dlg.style.display !== 'none' && dlg.style.display) return true;
  // Bookmarks sidebar (class-based)
  var sb = document.getElementById('bookmarksSidebar');
  if (sb && sb.classList.contains('open')) return true;
  // Workspace create modal
  var ws = document.getElementById('wsCreateModal');
  if (ws && ws.style.display !== 'none' && ws.style.display) return true;
  return false;
}

// Initial cache setup
if (window.electronAPI && window.electronAPI.getVimSettings) {
  window.electronAPI.getVimSettings().then(function(v) {
    if (!v) return;
    _vimCache.enabled = !!v.enabled;
    _vimRebuildCache(v.keys || {});
  }).catch(function(){});
}
// Live cache update when settings change
if (window.electronAPI && window.electronAPI.onVimSettingsChanged) {
  window.electronAPI.onVimSettingsChanged(function(vim) {
    if (!vim) return;
    _vimCache.enabled = !!vim.enabled;
    _vimRebuildCache(vim.keys || {});
  });
}

// Subscribe to modeChange from the active webview engine (via vim-action IPC)
// — this event is sent by the engine itself when the mode changes.
(function(){
  // Extend the existing onVimAction — it already listens to 'vim-action'.
  // But modeChange comes as {action:'modeChange', arg:mode}, we handle it
  // with a separate listener as part of the onVimAction callback below.
})();

// Chrome → webview forwarding is now handled via IPC from main.js
// (same place as regular hotkeys — this reliably always works). main.js
// sends 'forward-vim-key' for each key that MAY be a
// vim command; the renderer decides (no overlay / focus in input) and
// forwards it to the active webview.
(function() {
  if (!window.electronAPI || !window.electronAPI.onForwardVimKey) return;
  window.electronAPI.onForwardVimKey(function(info) {
    if (!_vimCache.enabled) return;
    if (_vimCache.mode === 'insert') return;  // do not intercept in INSERT
    if (!info || !info.key) return;
    // Focus in a chrome input field? Do not intercept (let the user type).
    if (_vimIsEditable(document.activeElement)) return;
    // Any chrome overlay open? Do not intercept.
    if (_vimChromeOverlayOpen()) return;
    // Active webview
    var tab = getActiveTab();
    if (!tab || !tab.webview) return;
    try { if (tab.webview.isDestroyed && tab.webview.isDestroyed()) return; } catch (_) { return; }
    var code = 'window.__spzVimInjectKey && window.__spzVimInjectKey(' +
      JSON.stringify(info.key) + ',' +
      !!info.shiftKey + ',' +
      !!info.ctrlKey + ',' +
      !!info.altKey + ',' +
      !!info.metaKey + ');';
    try { tab.webview.executeJavaScript(code).catch(function () {}); } catch (e) {}
  });
})();

// Hook mode updates: extend onShortcutAction (or use
// a separate channel) — the engine sends modeChange via the 'vim-action' IPC.
(function() {
  if (!window.electronAPI || !window.electronAPI.onVimAction) return;
  // onVimAction is already used by the block above — but IPC events reach us
  // multiple times (one per listener), so we add our own listener.
  // contextBridge.onXxx usually registers ONE ipcRenderer.on, but if
  // it allows multiple callbacks — a repeated call adds another one.
  // To avoid risk, we use the same callback via a patch:
  // (Only a comment is left here — modeChange is handled in onVimAction
  // above, in the switch case. We add case 'modeChange' there.)
})();

(function() {
  var abBtn = document.getElementById('adblockBtn');
  var abPanel = document.getElementById('adblockPanel');
  var abToggle = document.getElementById('abToggle');
  var abBlocked = document.getElementById('abBlocked');
  var abTrackers = document.getElementById('abTrackers');
  var abTotal = document.getElementById('abTotal');
  var abSiteName = document.getElementById('abSiteName');
  var abSiteToggle = document.getElementById('abSiteToggle');
  var abPanelOpen = false;

  function getActiveDomain() {
    var activeTab = tabs.find(function(t) { return t.id === activeTabId; });
    if (!activeTab || !activeTab.webview) return '';
    try {
      var url = activeTab.webview.getURL ? activeTab.webview.getURL() : (activeTab.webview.src || '');
      if (url.indexOf('file://') === 0 || url.indexOf('Settings.html') > -1 || url.indexOf('MainPage/index.html') > -1 || url.indexOf('ErrorPage/index.html') > -1) return '';
      return new URL(url).hostname.replace(/^www\./, '');
    } catch(e) { return ''; }
  }

  function updateAbStats() {
    if (!window.electronAPI || !window.electronAPI.adblockerIsEnabled) return;
    window.electronAPI.adblockerIsEnabled().then(function(r) {
      if (!r || !r.success) return;
      var on = r.enabled;
      abBtn.style.color = on ? '#28ca42' : '#666';
      if (abToggle) abToggle.checked = on;
    }).catch(function() {});

    var domain = getActiveDomain();
    if (abSiteName) abSiteName.textContent = domain || '—';

    if (domain && window.electronAPI.adblockerIsWhitelisted) {
      window.electronAPI.adblockerIsWhitelisted(domain).then(function(r) {
        if (r && r.whitelisted) {
          abSiteToggle.textContent = 'Whitelisted';
          abSiteToggle.classList.add('whitelisted');
        } else {
          abSiteToggle.textContent = 'Disable for this site';
          abSiteToggle.classList.remove('whitelisted');
        }
      }).catch(function() {});
    }
  }

  if (abBtn) {
    abBtn.addEventListener('click', function(e) {
      e.stopPropagation();
      abPanelOpen = !abPanelOpen;
      if (abPanelOpen) {
        updateAbStats();
        abPanel.classList.add('open');
      } else {
        abPanel.classList.remove('open');
      }
    });
  }

  if (abToggle) {
    abToggle.addEventListener('change', function() {
      if (window.electronAPI && window.electronAPI.adblockerToggle) {
        window.electronAPI.adblockerToggle(abToggle.checked).then(function() {
          abBtn.style.color = abToggle.checked ? '#28ca42' : '#666';
        });
      }
    });
  }

  if (abSiteToggle) {
    abSiteToggle.addEventListener('click', function() {
      var domain = getActiveDomain();
      if (!domain) return;
      if (abSiteToggle.classList.contains('whitelisted')) {
        window.electronAPI.adblockerRemoveWhitelist(domain).then(function() {
          abSiteToggle.textContent = 'Disable for this site';
          abSiteToggle.classList.remove('whitelisted');
        });
      } else {
        window.electronAPI.adblockerAddWhitelist(domain).then(function() {
          abSiteToggle.textContent = 'Whitelisted';
          abSiteToggle.classList.add('whitelisted');
        });
      }
    });
  }

  document.addEventListener('click', function(e) {
    if (abPanelOpen && abPanel && !abPanel.contains(e.target) && e.target !== abBtn) {
      abPanelOpen = false;
      abPanel.classList.remove('open');
    }
  });

  setInterval(function() {
    if (!abPanelOpen) return;
    if (!window.electronAPI || !window.electronAPI.adblockerGetStats) return;
    window.electronAPI.adblockerGetStats().then(function(r) {
      if (!r || !r.success) return;
      if (abBlocked) abBlocked.textContent = r.stats.session.ads || 0;
      if (abTrackers) abTrackers.textContent = r.stats.session.trackers || 0;
      if (abTotal) abTotal.textContent = r.stats.session.blocked || 0;
    }).catch(function() {});
  }, 2000);
})();


// ============== SCRIPTS PANEL (close + settings link) ==============
(function() {
  var mcPanel = document.getElementById('mediaPanel');
  var mcBtn = document.getElementById('mediaBtn');
  var siPanel = document.getElementById('siteInfoPanel');
  var siBtn = document.getElementById('urlIconBtn');
  if (mcPanel) {
    document.addEventListener('click', function(e) {
      if (mcPanel.classList.contains('open') && !mcPanel.contains(e.target) && e.target !== mcBtn && !mcBtn.contains(e.target)) {
        mcPanel.classList.remove('open');
        if (_mcRefreshTimer) { clearInterval(_mcRefreshTimer); _mcRefreshTimer = null; }
      }
      if (siPanel && siPanel.classList.contains('open') && !siPanel.contains(e.target) && e.target !== siBtn && !siBtn.contains(e.target)) {
        siPanel.classList.remove('open');
      }
      var eqP = document.getElementById('eqPanel');
      var eqB = document.getElementById('eqBtn');
      if (eqP && eqP.classList.contains('open') && !eqP.contains(e.target) && e.target !== eqB && !(eqB && eqB.contains(e.target))) {
        eqP.classList.remove('open');
      }
    });
  }

  var scPanel = document.getElementById('scriptsPanel');
  var scAdd = document.getElementById('scPanelAdd');
  var scSettings = document.getElementById('scPanelSettings');
  var scBtn = document.getElementById('scriptsBtn');

  if (scAdd) {
    scAdd.addEventListener('click', function() {
      scPanel.classList.remove('open');
      createNewTab('Settings.html#scripts');
    });
  }

  if (scSettings) {
    scSettings.addEventListener('click', function() {
      scPanel.classList.remove('open');
      createNewTab('Settings.html#scripts');
    });
  }

  document.addEventListener('click', function(e) {
    if (scPanel.classList.contains('open') && !scPanel.contains(e.target) && e.target !== scBtn) {
      scPanel.classList.remove('open');
    }
  });
})();

// ============== AUTOFILL PANEL ==============
(function() {
  var afBtn = document.getElementById('autofillBtn');
  var afPanel = document.getElementById('autofillPanel');
  var afPanelList = document.getElementById('afPanelList');
  var afPanelEmpty = document.getElementById('afPanelEmpty');
  var afPanelOpen = false;

  function escapeHtml(str) {
    var d = document.createElement('div');
    d.textContent = str;
    return d.innerHTML;
  }

  function renderAfList(passwords) {
    if (!passwords || passwords.length === 0) {
      afPanelList.innerHTML = '';
      afPanelEmpty.style.display = 'block';
      return;
    }
    afPanelEmpty.style.display = 'none';
    var html = '';
    passwords.forEach(function(pw) {
      html += '<div class="af-item" data-id="' + pw.id + '">';
      html += '<div class="af-item-icon"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 2l-2 2m-7.618 7.618a5.5 5.5 0 1 0-7.778 7.778 5.5 5.5 0 0 0 7.778-7.778zm0 0L15.5 7.5m0 0l3 3L22 7l-3-3"/></svg></div>';
      html += '<div class="af-item-info">';
      html += '<div class="af-item-site">' + escapeHtml(pw.site || '') + '</div>';
      html += '<div class="af-item-user">' + escapeHtml(pw.username || '') + '</div>';
      html += '</div>';
      html += '<button class="af-item-fill" data-id="' + pw.id + '">Fill</button>';
      html += '</div>';
    });
    afPanelList.innerHTML = html;

    afPanelList.querySelectorAll('.af-item-fill').forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.stopPropagation();
        var id = btn.getAttribute('data-id');
        if (window.electronAPI && window.electronAPI.autofillPassword) {
          window.electronAPI.autofillPassword(id).then(function(result) {
            afPanelOpen = false;
            afPanel.classList.remove('open');
          });
        }
      });
    });

    afPanelList.querySelectorAll('.af-item').forEach(function(item) {
      item.addEventListener('click', function() {
        var id = item.getAttribute('data-id');
        if (window.electronAPI && window.electronAPI.autofillPassword) {
          window.electronAPI.autofillPassword(id).then(function(result) {
            afPanelOpen = false;
            afPanel.classList.remove('open');
          });
        }
      });
    });
  }

  if (afBtn) {
    afBtn.addEventListener('click', function(e) {
      e.stopPropagation();
      afPanelOpen = !afPanelOpen;
      if (afPanelOpen) {
        var activeTab = tabs.find(function(t) { return t.id === activeTabId; });
        var currentUrl = '';
        if (activeTab && activeTab.webview) {
          try { currentUrl = activeTab.webview.getURL ? activeTab.webview.getURL() : (activeTab.webview.src || ''); } catch(e) { currentUrl = activeTab.webview.src || ''; }
        }
        if (currentUrl && window.electronAPI && window.electronAPI.getMatchingPasswords) {
          window.electronAPI.getMatchingPasswords(currentUrl).then(function(result) {
            var passwords = (result && result.passwords) || [];
            renderAfList(passwords);
          }).catch(function() { renderAfList([]); });
        } else {
          renderAfList([]);
        }
        afPanel.classList.add('open');
      } else {
        afPanel.classList.remove('open');
      }
    });
  }

  document.addEventListener('click', function(e) {
    if (afPanelOpen && afPanel && !afPanel.contains(e.target) && e.target !== afBtn) {
      afPanelOpen = false;
      afPanel.classList.remove('open');
    }
  });
})();

// ============== DOWNLOADS ==============
(function() {
  var dlBtn = document.getElementById('downloadsBtn');
  var dlPanel = document.getElementById('downloadPanel');
  var dlPanelList = document.getElementById('dlPanelList');
  var dlPanelEmpty = document.getElementById('dlPanelEmpty');
  var dlClearAll = document.getElementById('dlClearAll');
  var dlRingFill = dlBtn ? dlBtn.querySelector('.dl-ring-fill') : null;
  var CIRCUMFERENCE = 2 * Math.PI * 12; // 75.4

  var activeDownloads = {};
  var panelOpen = false;
  var downloadsCache = [];
  var fileExistsCache = {};

  function formatBytes(b) {
    if (b === 0) return '0 B';
    var k = 1024;
    var s = ['B', 'KB', 'MB', 'GB'];
    var i = Math.floor(Math.log(b) / Math.log(k));
    return parseFloat((b / Math.pow(k, i)).toFixed(1)) + ' ' + s[i];
  }

  var _fileIconSvg = {
    image: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>',
    video: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="2" width="20" height="20" rx="2.18" ry="2.18"/><line x1="7" y1="2" x2="7" y2="22"/><line x1="17" y1="2" x2="17" y2="22"/><line x1="2" y1="12" x2="22" y2="12"/><line x1="2" y1="7" x2="7" y2="7"/><line x1="2" y1="17" x2="7" y2="17"/><line x1="17" y1="17" x2="22" y2="17"/><line x1="17" y1="7" x2="22" y2="7"/></svg>',
    audio: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18V5l12-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/></svg>',
    pdf: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>',
    doc: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>',
    sheet: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="3" y1="15" x2="21" y2="15"/><line x1="9" y1="3" x2="9" y2="21"/><line x1="15" y1="3" x2="15" y2="21"/></svg>',
    slides: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="3" width="20" height="14" rx="2" ry="2"/><line x1="8" y1="21" x2="16" y2="21"/><line x1="12" y1="17" x2="12" y2="21"/></svg>',
    archive: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="21 8 21 21 3 21 3 8"/><rect x="1" y="3" width="22" height="5"/><line x1="10" y1="12" x2="14" y2="12"/></svg>',
    exe: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>',
    code: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="3" width="20" height="14" rx="2" ry="2"/><line x1="8" y1="21" x2="16" y2="21"/><line x1="12" y1="17" x2="12" y2="21"/></svg>',
    file: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>'
  };
  function getFileIcon(filename, mimeType) {
    var ext = (filename || '').split('.').pop().toLowerCase();
    var mime = (mimeType || '').toLowerCase();
    if (['jpg','jpeg','png','gif','webp','svg','bmp','ico'].indexOf(ext) >= 0 || mime.startsWith('image/'))
      return { icon: _fileIconSvg.image, bg: '#4a2c6a', color: '#c9a0ff' };
    if (['mp4','webm','mkv','avi','mov','wmv','flv'].indexOf(ext) >= 0 || mime.startsWith('video/'))
      return { icon: _fileIconSvg.video, bg: '#2d4a1e', color: '#7dd957' };
    if (['mp3','ogg','wav','flac','aac','m4a','wma'].indexOf(ext) >= 0 || mime.startsWith('audio/'))
      return { icon: _fileIconSvg.audio, bg: '#1e3a4a', color: '#57b8d9' };
    if (['pdf'].indexOf(ext) >= 0 || mime === 'application/pdf')
      return { icon: _fileIconSvg.pdf, bg: '#4a1e1e', color: '#ff6b6b' };
    if (['doc','docx','odt','rtf','txt'].indexOf(ext) >= 0 ||
        mime.indexOf('word') >= 0 || mime.indexOf('document') >= 0)
      return { icon: _fileIconSvg.doc, bg: '#1e2d4a', color: '#5790d9' };
    if (['xls','xlsx','csv','ods'].indexOf(ext) >= 0 || mime.indexOf('spreadsheet') >= 0 || mime.indexOf('excel') >= 0)
      return { icon: _fileIconSvg.sheet, bg: '#1e4a2d', color: '#57d97a' };
    if (['ppt','pptx','odp'].indexOf(ext) >= 0 || mime.indexOf('presentation') >= 0)
      return { icon: _fileIconSvg.slides, bg: '#4a3a1e', color: '#d9a857' };
    if (['zip','rar','7z','tar','gz','bz2','xz'].indexOf(ext) >= 0 || mime.indexOf('zip') >= 0 || mime.indexOf('compressed') >= 0)
      return { icon: _fileIconSvg.archive, bg: '#3d2d1e', color: '#d98a57' };
    if (['exe','msi','deb','rpm','dmg','appimage'].indexOf(ext) >= 0)
      return { icon: _fileIconSvg.exe, bg: '#2d2d2d', color: '#aaaaaa' };
    if (['js','ts','py','html','css','json','xml','java','cpp','c','h','rb','php','sh','go','rs'].indexOf(ext) >= 0)
      return { icon: _fileIconSvg.code, bg: '#1e4a4a', color: '#57d9c4' };
    return { icon: _fileIconSvg.file, bg: '#2d2d2d', color: '#aaaaaa' };
  }

  function updateButtonState() {
    if (!dlBtn) return;
    var hasActive = Object.keys(activeDownloads).length > 0;
    var hasDone = false;
    for (var id in activeDownloads) {
      if (activeDownloads[id] === 'completed') { hasDone = true; }
    }
    if (hasActive) {
      var allDone = Object.keys(activeDownloads).every(function(id) {
        return activeDownloads[id] === 'completed' || activeDownloads[id] === 'failed' || activeDownloads[id] === 'interrupted';
      });
      if (allDone) {
        dlBtn.classList.remove('dl-downloading');
        if (!dlBtn.classList.contains('dl-done')) dlBtn.classList.add('dl-done');
        if (dlRingFill) dlRingFill.style.strokeDashoffset = '0';
        var ringSvg = dlBtn.querySelector('.dl-progress-ring');
        if (ringSvg) ringSvg.style.display = 'none';
      } else {
        dlBtn.classList.remove('dl-done');
        dlBtn.classList.add('dl-downloading');
        var ringSvg2 = dlBtn.querySelector('.dl-progress-ring');
        if (ringSvg2) ringSvg2.style.display = 'block';
      }
    }
  }

  function renderDownloadsList() {
    if (!dlPanelList || !dlPanelEmpty) return;
    if (downloadsCache.length === 0) {
      dlPanelList.innerHTML = '';
      dlPanelEmpty.style.display = 'block';
      return;
    }
    dlPanelEmpty.style.display = 'none';
    var html = '';
    downloadsCache.forEach(function(dl) {
      var fi = getFileIcon(dl.filename, dl.mimeType);
      var isComplete = dl.state === 'completed';
      var isFailed = dl.state === 'failed' || dl.state === 'interrupted';
      var isProgressing = dl.state === 'progressing';
      var pct = (dl.totalBytes > 0) ? Math.round((dl.receivedBytes / dl.totalBytes) * 100) : 0;

      html += '<div class="dl-item" data-id="' + dl.id + '">';
      html += '<div class="dl-item-icon" style="background:' + fi.bg + ';color:' + fi.color + '">' + fi.icon + '</div>';
      html += '<div class="dl-item-info">';
      html += '<div class="dl-item-name" title="' + escapeHtmlSimple(dl.filename) + '">' + escapeHtmlSimple(dl.filename) + '</div>';

      if (isProgressing) {
        html += '<div class="dl-item-meta"><span class="dl-status-progress">' + pct + '% — ' + formatBytes(dl.receivedBytes);
        if (dl.totalBytes > 0) html += ' / ' + formatBytes(dl.totalBytes);
        html += '</span></div>';
        html += '<div class="dl-item-progress"><div class="dl-item-progress-bar" style="width:' + pct + '%"></div></div>';
      } else if (isComplete) {
        var fileMissing = dl.path && fileExistsCache[dl.path] === false;
        if (fileMissing) {
          html += '<div class="dl-item-meta"><span class="dl-status-done">' + formatBytes(dl.totalBytes || dl.receivedBytes) + '</span></div>';
          html += '<div class="dl-item-meta"><span class="dl-status-missing">File was moved or deleted</span></div>';
        } else {
          html += '<div class="dl-item-meta"><span class="dl-status-done">' + formatBytes(dl.totalBytes || dl.receivedBytes) + ' — Done</span></div>';
        }
      } else {
        html += '<div class="dl-item-meta"><span class="dl-status-failed">Error</span></div>';
      }

      html += '</div>';
      html += '<div class="dl-item-actions">';
      if (isComplete) {
        html += '<button class="dl-open-file" data-path="' + (dl.path || '').replace(/"/g, '&quot;') + '" title="Open file"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:middle"><polygon points="5 3 19 12 5 21 5 3"/></svg></button>';
        html += '<button class="dl-open-folder" data-path="' + (dl.path || '').replace(/"/g, '&quot;') + '" title="Show in folder"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:middle"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg></button>';
      }
      html += '</div>';
      html += '</div>';
    });
    dlPanelList.innerHTML = html;

    dlPanelList.querySelectorAll('.dl-open-file').forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.stopPropagation();
        if (window.electronAPI && window.electronAPI.openDownloadFile) {
          window.electronAPI.openDownloadFile(btn.getAttribute('data-path'));
        }
      });
    });
    dlPanelList.querySelectorAll('.dl-open-folder').forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.stopPropagation();
        if (window.electronAPI && window.electronAPI.openDownloadFolder) {
          window.electronAPI.openDownloadFolder(btn.getAttribute('data-path'));
        }
      });
    });
  }

  async function refreshDownloads() {
    if (window.electronAPI) {
      if (window.electronAPI.getSessionDownloads) {
        downloadsCache = await window.electronAPI.getSessionDownloads();
      } else if (window.electronAPI.getDownloads) {
        downloadsCache = await window.electronAPI.getDownloads();
      }
      var paths = downloadsCache.filter(function(d) { return d.state === 'completed' && d.path; }).map(function(d) { return d.path; });
      paths = paths.filter(function(p, i, a) { return a.indexOf(p) === i; });
      if (paths.length > 0 && window.electronAPI.checkFilesExist) {
        var existMap = await window.electronAPI.checkFilesExist(paths);
        fileExistsCache = Object.assign(fileExistsCache, existMap);
      }
      renderDownloadsList();
    }
  }

  if (dlBtn) {
    dlBtn.addEventListener('click', function(e) {
      e.stopPropagation();
      panelOpen = !panelOpen;
      if (panelOpen) {
        dlPanel.classList.add('open');
        refreshDownloads();
        dlBtn.classList.remove('dl-done');
        activeDownloads = {};
      } else {
        dlPanel.classList.remove('open');
      }
    });
  }

  document.addEventListener('click', function(e) {
    if (panelOpen && dlPanel && !dlPanel.contains(e.target) && e.target !== dlBtn) {
      panelOpen = false;
      dlPanel.classList.remove('open');
    }
  });

  if (dlClearAll) {
    dlClearAll.addEventListener('click', function() {
      if (window.electronAPI && window.electronAPI.clearDownloads) {
        window.electronAPI.clearDownloads().then(function() {
          downloadsCache = [];
          renderDownloadsList();
        });
      }
    });
  }

  if (window.electronAPI) {
    if (window.electronAPI.onDownloadStarted) {
      window.electronAPI.onDownloadStarted(function(info) {
        activeDownloads[info.id] = 'progressing';
        updateButtonState();
        if (panelOpen) refreshDownloads();
      });
    }

    if (window.electronAPI.onDownloadProgress) {
      window.electronAPI.onDownloadProgress(function(info) {
        if (info.state === 'progressing') {
          activeDownloads[info.id] = 'progressing';
          if (dlBtn && dlBtn.classList.contains('dl-downloading') && dlRingFill && info.totalBytes > 0) {
            var pct = info.receivedBytes / info.totalBytes;
            dlRingFill.style.strokeDashoffset = CIRCUMFERENCE * (1 - pct);
          }
          if (panelOpen) {
            var idx = downloadsCache.findIndex(function(d) { return d.id === info.id; });
            if (idx >= 0) {
              downloadsCache[idx].receivedBytes = info.receivedBytes;
              downloadsCache[idx].totalBytes = info.totalBytes;
              downloadsCache[idx].state = 'progressing';
            }
            renderDownloadsList();
          }
        } else if (info.state === 'completed' || info.state === 'failed' || info.state === 'interrupted') {
          activeDownloads[info.id] = info.state;
          updateButtonState();
          if (panelOpen) refreshDownloads();
        }
      });
    }

    if (window.electronAPI.onDownloadsUpdated) {
      window.electronAPI.onDownloadsUpdated(function() {
        if (panelOpen) refreshDownloads();
      });
    }
  }
})();

// ============== QR PAGE SCANNER ==============
var _qrFoundData = {};
var _qrVisibleTab = null;
var _qrScanning = false;
var _qrOverlayExists = {};
var _qrLastState = {};
var _qrEnabled = false;
var _qrTimerId = null;

function _qrStop() {
  if (_qrTimerId) { clearTimeout(_qrTimerId); _qrTimerId = null; }
  _qrScanning = false;
  for (var tid in _qrOverlayExists) {
    var t = tabs.find(function(x) { return x.id === tid; });
    if (t && t.webview && t.isReady) {
      try { t.webview.executeJavaScript('var f=document.getElementById("__qr_scan_frame");if(f)f.remove();'); } catch(e) {}
    }
  }
  _qrOverlayExists = {};
  _qrLastState = {};
  _qrFoundData = {};
  _qrVisibleTab = null;
}

function _qrStart() {
  _qrLoop();
}

function _qrLoop() {
  if (!_qrEnabled) return;
  if (_qrScanning) { _qrTimerId = setTimeout(_qrLoop, 50); return; }
  var tab = tabs.find(function(t) { return t.id === activeTabId; });
  if (!tab || !tab.webview || !tab.isReady) { _qrTimerId = setTimeout(_qrLoop, 100); return; }
  var src = '';
  try { src = tab.webview.getURL ? tab.webview.getURL() : (tab.webview.src || ''); } catch(e) { src = tab.webview.src || ''; }
  if (!src || src.indexOf('file://') === 0 || src.indexOf('Settings.html') > -1 || src.indexOf('MainPage/index.html') > -1 || src.indexOf('ErrorPage/index.html') > -1) { _qrTimerId = setTimeout(_qrLoop, 200); return; }
  if (tab.webview.isLoading && tab.webview.isLoading()) { _qrTimerId = setTimeout(_qrLoop, 100); return; }
  scanTabForQR(tab, function() {
    if (_qrEnabled) _qrTimerId = setTimeout(_qrLoop, 0);
  });
}

function scanTabForQR(tabData, onDone) {
  if (!tabData || !tabData.webview || !tabData.isReady || !_qrEnabled) { _qrScanning = false; return; }
  _qrScanning = true;
  try {
    if (tabData.webview.isDestroyed && tabData.webview.isDestroyed()) { _qrScanning = false; return; }
    tabData.webview.capturePage().then(function(nativeImage) {
      _qrScanning = false;
      if (!_qrEnabled) return;
      if (!nativeImage || nativeImage.isEmpty()) { if (_qrEnabled && onDone) onDone(); return; }
      try {
        var size = nativeImage.getSize();
        if (!size || size.width < 20 || size.height < 20) { if (_qrEnabled && onDone) onDone(); return; }
        var c = document.createElement('canvas');
        var ctx = c.getContext('2d');
        var scale = Math.min(size.width, size.height) > 800 ? 800 / Math.min(size.width, size.height) : 1;
        c.width = Math.round(size.width * scale);
        c.height = Math.round(size.height * scale);
        var imgEl = new Image();
        imgEl.onload = function() {
          if (!_qrEnabled) return;
          ctx.drawImage(imgEl, 0, 0, c.width, c.height);
          try {
            var imageData = ctx.getImageData(0, 0, c.width, c.height);
            if (typeof jsQR === 'function') {
              var code = jsQR(imageData.data, imageData.width, imageData.height, { inversionAttempts: 'dontInvert' });
              if (code && code.data) {
                var loc = code.location;
                var pts = [loc.topLeftCorner, loc.topRightCorner, loc.bottomRightCorner, loc.bottomLeftCorner];
                var minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
                for (var pi = 0; pi < pts.length; pi++) {
                  if (pts[pi].x < minX) minX = pts[pi].x;
                  if (pts[pi].y < minY) minY = pts[pi].y;
                  if (pts[pi].x > maxX) maxX = pts[pi].x;
                  if (pts[pi].y > maxY) maxY = pts[pi].y;
                }
                var bx = minX / scale;
                var by = minY / scale;
                var bw = (maxX - minX) / scale;
                var bh = (maxY - minY) / scale;
                _qrFoundData[tabData.id] = code.data;
                _qrVisibleTab = tabData.id;
                showQrOverlay(tabData, code.data, bx, by, bw, bh);
              } else {
                if (_qrVisibleTab === tabData.id) {
                  _qrFoundData[tabData.id] = null;
                  _qrVisibleTab = null;
                  hideQrOverlay(tabData);
                }
              }
            }
          } catch(e) {}
          if (_qrEnabled && onDone) onDone();
        };
        imgEl.src = nativeImage.toDataURL();
      } catch(e) { if (_qrEnabled && onDone) onDone(); }
    }).catch(function() { _qrScanning = false; if (_qrEnabled && onDone) onDone(); });
  } catch(e) { _qrScanning = false; if (_qrEnabled && onDone) onDone(); }
}

function showQrOverlay(tabData, qrData, bx, by, bw, bh) {
  if (!tabData || !tabData.webview) return;
  if (!canExecInWebview(tabData.webview)) return;
  var pad = 8;
  var sBx = Math.round(bx - pad);
  var sBy = Math.round(by - pad);
  var sBw = Math.round(Math.max(bw, 30) + pad * 2);
  var sBh = Math.round(Math.max(bh, 30) + pad * 2);
  var isUrl = /^https?:\/\//i.test(qrData);
  var displayText = qrData.length > 50 ? qrData.substring(0, 50) + '...' : qrData;
  var escData = qrData.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/"/g, '\\"');
  var escDisplay = displayText.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/"/g, '\\"').replace(/</g, '\\x3c').replace(/>/g, '\\x3e');
  var actionLabel = isUrl ? 'Open \u2192' : 'Copy';

  if (_qrOverlayExists[tabData.id]) {
    var st = _qrLastState[tabData.id];
    if (st && st.data === qrData && st.sBx === sBx && st.sBy === sBy && st.sBw === sBw && st.sBh === sBh) return;
    _qrLastState[tabData.id] = { data: qrData, sBx: sBx, sBy: sBy, sBw: sBw, sBh: sBh };
    tabData.webview.executeJavaScript(
      '(function(){' +
      'var f=document.getElementById("__qr_scan_frame");' +
      'if(f){' +
      'f.style.left="' + sBx + 'px";f.style.top="' + sBy + 'px";f.style.width="' + sBw + 'px";f.style.height="' + sBh + 'px";' +
      'f.classList.remove("__qr_hidden");' +
      'var t=f.querySelector(".__qr_txt");if(t)t.textContent="' + escDisplay + '";' +
      'var a=f.querySelector(".__qr_act");if(a)a.textContent="' + actionLabel + '";' +
      '}' +
      '})()'
    ).catch(function() {});
    return;
  }

  _qrOverlayExists[tabData.id] = true;

  var script =
    '(function(){' +
    'if(!document.getElementById("__qr_scan_style")){' +
    'var s=document.createElement("style");' +
    's.id="__qr_scan_style";' +
    's.textContent=' +
    '".__qr_wrap{position:fixed;z-index:2147483647;cursor:pointer;font-family:system-ui,-apple-system,sans-serif;transition:opacity 0.2s}" +' +
    '".__qr_wrap.__qr_hidden{opacity:0;pointer-events:none}" +' +
    '".__qr_wrap:hover .__qr_border{border-color:rgba(29,161,242,1);background:rgba(29,161,242,0.08);box-shadow:0 0 14px rgba(29,161,242,0.5),0 0 4px rgba(29,161,242,0.8)}" +' +
    '".__qr_border{border:2.5px solid rgba(29,161,242,0.9);border-radius:8px;transition:border-color 0.15s,background 0.15s,box-shadow 0.15s;pointer-events:none;box-shadow:0 0 8px rgba(29,161,242,0.35),0 0 2px rgba(29,161,242,0.6)}" +' +
    '".__qr_info{display:flex;align-items:center;gap:6px;margin-top:4px;pointer-events:none}" +' +
    '".__qr_txt{font-size:10px;color:#1da1f2;background:rgba(255,255,255,0.92);padding:2px 8px;border-radius:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:' + Math.max(sBw - 8, 60) + 'px;text-align:center;line-height:1.4}";' +
    'document.head.appendChild(s);' +
    '}' +
    'var w=document.createElement("div");' +
    'w.id="__qr_scan_frame";' +
    'w.className="__qr_wrap";' +
    'w.style.left="' + sBx + 'px";' +
    'w.style.top="' + sBy + 'px";' +
    'var b=document.createElement("div");' +
    'b.className="__qr_border";' +
    'b.style.width="' + sBw + 'px";' +
    'b.style.height="' + sBh + 'px";' +
    'var inf=document.createElement("div");' +
    'inf.className="__qr_info";' +
    'var txt=document.createElement("div");' +
    'txt.className="__qr_txt";' +
    'txt.textContent="' + escDisplay + '";' +
    'inf.appendChild(txt);' +
    'w.appendChild(b);' +
    'w.appendChild(inf);' +
    'w.addEventListener("click",function(e){' +
    '  e.stopPropagation();e.preventDefault();' +
    '  try{' +
    '    var fsEl=document.fullscreenElement||document.webkitFullscreenElement;' +
    '    if(fsEl){(document.exitFullscreen||document.webkitExitFullscreen).call(document);}' +
    '  }catch(ex){}' +
    (isUrl
      ? '  window.postMessage({type:"__QR_OPEN_URL",url:"' + escData + '"},"*");'
      : '  navigator.clipboard.writeText("' + escData + '").catch(function(){});')
    + '});' +
    'document.documentElement.appendChild(w);' +
    '})()';

  tabData.webview.executeJavaScript(script).catch(function() {});
}

function hideQrOverlay(tabData) {
  if (!tabData || !tabData.webview) return;
  if (!canExecInWebview(tabData.webview)) return;
  tabData.webview.executeJavaScript(
    '(function(){' +
    'var f=document.getElementById("__qr_scan_frame");' +
    'if(f&&!f.classList.contains("__qr_hidden"))f.classList.add("__qr_hidden");' +
    '})()'
  ).catch(function() {});
}

function removeQrOverlay(tabData) {
  if (!tabData || !tabData.webview) return;
  _qrOverlayExists[tabData.id] = false;
  _qrLastState[tabData.id] = null;
  if (!canExecInWebview(tabData.webview)) return;
  tabData.webview.executeJavaScript(
    '(function(){' +
    'var f=document.getElementById("__qr_scan_frame");' +
    'if(f)f.remove();' +
    '})()'
  ).catch(function() {});
}

_qrLoop();

function escapeHtmlSimple(str) {
  var d = document.createElement('div');
  d.textContent = str;
  return d.innerHTML.replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

// ============== SECURITY FEATURES ==============
var _secSettings = {};
function loadSecSettings() {
  if (!window.electronAPI || !window.electronAPI.getAllSecuritySettings) return;
  window.electronAPI.getAllSecuritySettings().then(function(s) {
    _secSettings = s || {};
    _applyLetterboxing();
  });
}
loadSecSettings();
if (window.electronAPI && window.electronAPI.onSecuritySettingsChanged) {
  window.electronAPI.onSecuritySettingsChanged(function(_, s) {
    _secSettings = s || {};
    _applyLetterboxing();
  });
}

// ============== LETTERBOXING ==============
var _letterboxingStyle = null;
function _applyLetterboxing() {
  var enabled = !!(_secSettings && _secSettings.letterboxing);
  var bc = document.querySelector('.browser-content');
  if (!bc) return;

  if (!enabled) {
    if (_letterboxingStyle) { _letterboxingStyle.remove(); _letterboxingStyle = null; }
    bc.classList.remove('letterboxed');
    return;
  }

  if (!_letterboxingStyle) {
    _letterboxingStyle = document.createElement('style');
    _letterboxingStyle.id = 'letterboxing-css';
    _letterboxingStyle.textContent =
      '.browser-content.letterboxed { background: var(--bg-color-alpha, rgba(32,32,32,1)) !important; }\n' +
      '.browser-content.letterboxed webview {\n' +
      '  width: var(--lb-w, 100%) !important;\n' +
      '  height: var(--lb-h, 100%) !important;\n' +
      '  left: var(--lb-x, 0) !important;\n' +
      '  top: var(--lb-y, 0) !important;\n' +
      '  border-radius: 8px !important;\n' +
      '  overflow: hidden !important;\n' +
      '}\n';
    document.head.appendChild(_letterboxingStyle);
  }

  bc.classList.add('letterboxed');

  var w = bc.clientWidth;
  var h = bc.clientHeight;
  var stepW = 200;
  var stepH = 100;
  var rw = Math.max(stepW, Math.floor(w / stepW) * stepW);
  var rh = Math.max(stepH, Math.floor(h / stepH) * stepH);
  var px = Math.floor((w - rw) / 2);
  var py = Math.floor((h - rh) / 2);
  bc.style.setProperty('--lb-w', rw + 'px');
  bc.style.setProperty('--lb-h', rh + 'px');
  bc.style.setProperty('--lb-x', px + 'px');
  bc.style.setProperty('--lb-y', py + 'px');
}

window.addEventListener('resize', function() {
  if (_secSettings && _secSettings.letterboxing) _applyLetterboxing();
});
window.addEventListener('DOMContentLoaded', function() { _applyLetterboxing(); });
setTimeout(_applyLetterboxing, 500);

var _optSettings = {};
function loadOptSettings() {
  if (!window.electronAPI || !window.electronAPI.getAllOptimizationSettings) return;
  window.electronAPI.getAllOptimizationSettings().then(function(o) {
    _optSettings = o || {};
    try { _syncEcoAll(); } catch(e) {}
  });
}
loadOptSettings();
if (window.electronAPI && window.electronAPI.onOptimizationSettingsChanged) {
  window.electronAPI.onOptimizationSettingsChanged(function() { loadOptSettings(); });
}

// ============== TASK MANAGER + OPTIMIZATION (extension) ==============
// Whitelist of domains that "never sleep" (domain + subdomains).
function _noSleepList() {
  var arr = _optSettings && _optSettings.noSleepDomains;
  return Array.isArray(arr) ? arr : [];
}
function isDomainNoSleep(url) {
  var list = _noSleepList();
  if (!list.length) return false;
  var host = '';
  try { host = new URL(url).hostname.toLowerCase(); } catch(e) { return false; }
  if (!host) return false;
  for (var i = 0; i < list.length; i++) {
    var d = String(list[i]).trim().toLowerCase();
    if (!d) continue;
    if (host === d || host.endsWith('.' + d)) return true;
  }
  return false;
}

// Clear Service Workers for a tab before sleeping (if enabled).
// Safe: unregisterSW only for the current page origin. On the next
// visit the site will register the SW again.
function _maybeClearSWBeforeSleep(tab) {
  if (!_optSettings || !_optSettings.clearSleepingSW) return;
  if (!tab || !tab.webview || !tab.isReady) return;
  try {
    if (!canExecInWebview(tab.webview)) return;
    tab.webview.executeJavaScript(
      '(function(){try{if(navigator.serviceWorker&&navigator.serviceWorker.getRegistrations){navigator.serviceWorker.getRegistrations().then(function(rs){rs.forEach(function(r){try{r.unregister()}catch(e){}})})}}catch(e){}})()'
    ).catch(function(){});
  } catch(e) {}
}

// Put a tab to sleep (wrapper over existing logic with whitelist and SW checks).
// Returns true if the tab was put to sleep.
function _sleepTabSafe(tab) {
  if (!tab || !tab.webview || !tab.isReady || tab._isSleeping) return false;
  if (tab.id === activeTabId) return false;
  // URL for whitelist check
  var url = '';
  try { url = tab.webview.getURL ? tab.webview.getURL() : tab.webview.src; } catch(e) { url = tab.lastUrl || ''; }
  if (!url) url = tab.lastUrl || '';
  if (isDomainNoSleep(url)) return false; // whitelist — do not touch
  if (url.indexOf('file://') === 0) return false;
  // Do not sleep if media is playing in the tab
  // (check is done by the caller for timer/memory; here is the sync version — skipped)
  _maybeClearSWBeforeSleep(tab);
  tab._sleepUrl = url;
  tab.pendingUrl = url;
  tab.lastUrl = null;
  try { tab.webview.loadURL('about:blank'); } catch(e) {}
  tab._isSleeping = true;
  var el = document.querySelector('[data-tab-id="' + tab.id + '"]');
  if (el) {
    el.classList.add('tab-sleeping');
    var fav = el.querySelector('.tab-favicon, .tab-favicon-placeholder');
    if (fav) fav.classList.add('tab-sleeping-favicon');
  }
  return true;
}

// Put all tabs to sleep except the active one.
function sleepAllTabsExceptActive() {
  var count = 0;
  tabs.forEach(function(tab) {
    if (tab.id === activeTabId) return;
    // Skip tabs with active media (async check is not suitable —
    // best-effort: check synchronously via flag, otherwise sleep).
    if (_sleepTabSafe(tab)) count++;
  });
  return count;
}

// Open/focus the Task Manager.
function openTaskManager() {
  var existing = tabs.find(function(t) {
    try {
      var u = t.webview && t.webview.src ? t.webview.src : '';
      return u && u.indexOf('TaskManager.html') !== -1;
    } catch(e) { return false; }
  });
  if (existing) {
    setActiveTab(existing.id);
    return;
  }
  createNewTab('TaskManager.html');
}

// Polling: send a fresh tab snapshot (with pid) to main ONLY when
// Task Manager is open. main merges this with app.getAppMetrics() and passes it to
// TaskManager.html. Continuous polling caused browser lag.
var _tmPollTimer = null;
function _isTaskManagerOpen() {
  return tabs.some(function(t) {
    try {
      var u = t.webview ? (t.webview.src || '') : '';
      return u && u.indexOf('TaskManager.html') !== -1;
    } catch(e) { return false; }
  });
}
function _startTaskManagerPolling() {
  if (_tmPollTimer) clearInterval(_tmPollTimer);
  if (!window.electronAPI || !window.electronAPI.sendTabInfos) return;
  _tmPollTimer = setInterval(function() {
    if (!_isTaskManagerOpen()) return;
    try {
      var infos = tabs.map(function(t) {
        var pid = null;
        try { if (t.webview && t.webview.getProcessId) pid = t.webview.getProcessId(); } catch(e) {}
        var url = '';
        try { url = t.webview && t.webview.getURL ? t.webview.getURL() : (t.webview ? t.webview.src : ''); } catch(e) {}
        if (!url || url === 'about:blank') url = (t._isSleeping && t._sleepUrl) ? t._sleepUrl : (t.lastUrl || '');
        // Name and favicon are read from the tab bar DOM — this is the authoritative source:
        // works for sleeping tabs too (about:blank), since label/fav in the tab
        // are preserved when sleeping.
        var title = t.title || '';
        var favicon = '';
        try {
          var tabEl = document.querySelector('[data-tab-id="' + t.id + '"]');
          if (tabEl) {
            var titleEl = tabEl.querySelector('.tab-title');
            if (titleEl) { var tx = (titleEl.textContent || '').trim(); if (tx) title = tx; }
            var favImg = tabEl.querySelector('.tab-favicon');
            if (favImg && favImg.src) favicon = favImg.src;
          }
        } catch(e) {}
        if (!title && !t._isSleeping) {
          try { if (t.webview && t.webview.getTitle) title = t.webview.getTitle() || ''; } catch(e) {}
        }
        var hostname = '';
        try { if (url && url.indexOf('http') === 0) hostname = new URL(url).hostname; } catch(e) {}
        return {
          id: t.id,
          pid: pid,
          title: title,
          url: url,
          hostname: hostname,
          favicon: favicon,
          isSleeping: !!t._isSleeping,
          isFrozen: !!t._ecoFrozen,
          isActive: t.id === activeTabId,
          isPinned: !!t.pinned,
          isWhitelisted: isDomainNoSleep(url)
        };
      });
      window.electronAPI.sendTabInfos(infos);
    } catch(e) {}
  }, 2000);
}
_startTaskManagerPolling();

// ============== ECO-FREEZE (freezing background tab animations) ==============
// Solves the "multiple tabs with animations = lag" problem: in inactive
// tabs CSS animations/rAF are paused (engine in preload-webview.js).
// Media (video/audio) is NOT touched. "Never sleep" whitelist exempt.
function _ecoTabUrl(tab) {
  if (!tab) return '';
  var url = '';
  try { url = tab.webview && tab.webview.getURL ? tab.webview.getURL() : (tab.webview ? tab.webview.src : ''); } catch(e) {}
  if (!url || url === 'about:blank') url = (tab._isSleeping && tab._sleepUrl) ? tab._sleepUrl : (tab.lastUrl || '');
  return url || '';
}
function _ecoSetTab(tab, on) {
  if (!tab || !tab.webview || !tab.webview.send) return;
  if (!!tab._ecoFrozen === !!on) return; // already in the desired state
  try { tab.webview.send('eco-freeze', { on: !!on }); } catch(e) { return; }
  tab._ecoFrozen = !!on;
}
// Desired freeze state for a tab considering all factors.
function _ecoDesiredOn(tab) {
  if (!tab || !tab.webview || !tab.isReady) return false;
  if (tab.id === activeTabId) return false;        // do not freeze the active tab
  if (tab._isSleeping) return false;               // already about:blank
  if (isDomainNoSleep(_ecoTabUrl(tab))) return false; // whitelist exempt
  if (_optSettings.ecoFreeze !== false) return true;  // ON by default (undefined → enabled)
  if (_optSettings.ecoCpuGuard && tab._ecoCpuForced) return true; // auto by CPU
  return false;
}
function _syncEcoForTab(tab) {
  if (!tab) return;
  var want = _ecoDesiredOn(tab);
  _ecoSetTab(tab, want);
}
function _syncEcoAll() {
  tabs.forEach(_syncEcoForTab);
}

// Real optimization: CPU poller. If a background tab consumes CPU above the threshold
// for N ticks in a row → force freeze (even if ecoFreeze is disabled, but
// ecoCpuGuard is enabled).
var _ecoCpuTimer = null;
function _startEcoCpuGuard() {
  if (_ecoCpuTimer) clearInterval(_ecoCpuTimer);
  _ecoCpuTimer = setInterval(function() {
    try {
      if (!_optSettings || !_optSettings.ecoCpuGuard) {
        // if guards are disabled — remove forced flags
        tabs.forEach(function(t) { if (t._ecoCpuForced) { t._ecoCpuForced = false; t._ecoCpuHeavyTicks = 0; _syncEcoForTab(t); } });
        return;
      }
      if (!window.electronAPI || !window.electronAPI.getTaskManagerData) return;
      var threshold = parseInt(_optSettings.ecoCpuThreshold) || 15;
      window.electronAPI.getTaskManagerData().then(function(data) {
        var byId = {};
        (data && data.tabs || []).forEach(function(r) { if (r && r.tabId) byId[r.tabId] = r; });
        tabs.forEach(function(tab) {
          var r = byId[tab.id];
          var cpu = r ? (r.cpu || 0) : 0;
          if (cpu >= threshold && tab.id !== activeTabId) {
            tab._ecoCpuHeavyTicks = (tab._ecoCpuHeavyTicks || 0) + 1;
          } else {
            tab._ecoCpuHeavyTicks = 0;
          }
          var wasForced = !!tab._ecoCpuForced;
          tab._ecoCpuForced = (tab._ecoCpuHeavyTicks || 0) >= 2; // ~6 sec of continuous heavy load
          if (tab._ecoCpuForced !== wasForced) _syncEcoForTab(tab);
        });
      });
    } catch(e) {}
  }, 5000);
}
_startEcoCpuGuard();

// Resync eco when optimization settings change (ecoFreeze/ecoCpuGuard).
// loadOptSettings is async — hook the same event.
if (window.electronAPI && window.electronAPI.onOptimizationSettingsChanged && !window.__ecoOptHooked) {
  window.__ecoOptHooked = true;
  window.electronAPI.onOptimizationSettingsChanged(function() {
    // _optSettings will update in loadOptSettings(); give it time, then sync
    setTimeout(function() {
      try { loadOptSettings(); } catch(e) {}
      // loadOptSettings is also async — read directly for reliability
      if (window.electronAPI && window.electronAPI.getAllOptimizationSettings) {
        window.electronAPI.getAllOptimizationSettings().then(function(o) {
          _optSettings = o || {};
          _syncEcoAll();
          _syncDataSaverAll();
          _applyBatterySaver();
        });
      } else {
        _syncEcoAll();
      }
    }, 50);
  });
}

// ============== DATA SAVER sync ==============
function _dataSaverOn() {
  return !!(_optSettings && _optSettings.dataSaver);
}
function _syncDataSaverForTab(tab) {
  if (!tab || !tab.webview || !tab.webview.send) return;
  try { tab.webview.send('data-saver', { on: _dataSaverOn() }); } catch(e) {}
}
function _syncDataSaverAll() {
  tabs.forEach(_syncDataSaverForTab);
}

// ============== BATTERY SAVER ==============
var _batteryState = null;
function _batterySaverActive() {
  if (!_optSettings || !_optSettings.batterySaver) return false;
  if (!_batteryState) return false;
  return !_batteryState.charging && _batteryState.level < 0.20;
}
function _applyBatterySaver() {
  var active = _batterySaverActive();
  var ecoWasFrozen = {};
  tabs.forEach(function(t) {
    if (t && t._ecoFrozen) ecoWasFrozen[t.id] = true;
  });
  _syncDataSaverAll();
  if (active) {
    tabs.forEach(function(t) {
      if (t && t.webview && t.webview.send && t.id !== activeTabId) {
        try { t.webview.send('data-saver', { on: true }); } catch(e) {}
      }
    });
  }
}
if (navigator.getBattery) {
  navigator.getBattery().then(function(battery) {
    _batteryState = { level: battery.level, charging: battery.charging };
    battery.addEventListener('levelchange', function() {
      _batteryState.level = battery.level;
      _applyBatterySaver();
    });
    battery.addEventListener('chargingchange', function() {
      _batteryState.charging = battery.charging;
      _applyBatterySaver();
    });
    _applyBatterySaver();
  }).catch(function() {});
}


if (window.electronAPI && window.electronAPI.onTaskManagerAction) {
  window.electronAPI.onTaskManagerAction(function(data) {
    if (!data || !data.action) return;
    var tabId = data.tabId;
    var tab = tabs.find(function(t) { return t.id === tabId; });
    switch (data.action) {
      case 'sleepAll': {
        var n = sleepAllTabsExceptActive();
        try { _showToast && _showToast('Tabs put to sleep: ' + n); } catch(e) {}
        break;
      }
      case 'close':
        if (tab && tabs.length > 1) closeTab(tabId);
        break;
      case 'sleep':
        if (tab) {
          if (tab.id === activeTabId) return;
          // async media check
          try {
            tab.webview.executeJavaScript(
              '(function(){var vs=document.querySelectorAll("video");for(var i=0;i<vs.length;i++){try{if(!vs[i].paused&&vs[i].currentTime>0)return"playing";}catch(e){}}return"idle";})()'
            ).then(function(st) {
              if (st !== 'playing') _sleepTabSafe(tab);
            }).catch(function(){});
          } catch(e) { _sleepTabSafe(tab); }
        }
        break;
      case 'activate':
        if (tab) setActiveTab(tabId);
        break;
      case 'reload':
        if (tab && tab.webview) {
          if (tab._isSleeping) wakeUpTab(tab);
          try { tab.webview.reload(); } catch(e) {}
        }
        break;
    }
  });
}

// --- Tab Sleep ---
var _tabSleepTimers = {};
var _tabGroups = [];
try { var _tg = localStorage.getItem('startpozi-tab-groups'); if (_tg) _tabGroups = JSON.parse(_tg); } catch(e) {}
function _saveTabGroups() { try { localStorage.setItem('startpozi-tab-groups', JSON.stringify(_tabGroups)); } catch(e) {} }

function _renderTabGroupHeaders() {
  document.querySelectorAll('.tab-group-header').forEach(function(el) { el.remove(); });
  if (!_tabGroups.length) return;
  var tabsBar = document.querySelector('.tabs-bar');
  var newTabBtn = document.getElementById('newTabBtn');
  _tabGroups.forEach(function(group) {
    var groupTabIds = tabs.filter(function(t) { return t.groupId === group.id; }).map(function(t) { return t.id; });
    if (!groupTabIds.length) return;
    var firstIdx = tabs.findIndex(function(t) { return t.id === groupTabIds[0]; });
    if (firstIdx === -1) return;
    var refEl = tabs[firstIdx].element;
    var header = document.createElement('div');
    header.className = 'tab-group-header';
    header.dataset.groupId = group.id;
    header.innerHTML = '<span class="tab-group-dot" style="background:' + (group.color || '#4a90d9') + '"></span>' +
      '<span class="tab-group-name">' + (group.name || 'Group') + '</span>' +
      '<span class="tab-group-count">' + groupTabIds.length + '</span>' +
      (group.collapsed ? '<svg class="tab-group-expand" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>' : '');
    header.style.borderLeftColor = group.color || '#4a90d9';
    if (group.collapsed) header.classList.add('tab-group-collapsed');
    header.addEventListener('click', function(e) {
      e.stopPropagation();
      group.collapsed = !group.collapsed;
      _saveTabGroups();
      _renderTabGroupHeaders();
      _applyGroupCollapse(group.id, group.collapsed);
    });
    tabsBar.insertBefore(header, refEl);
  });
}

function _applyGroupCollapse(groupId, collapsed) {
  tabs.forEach(function(t) {
    if (t.groupId === groupId) {
      t.element.style.display = collapsed ? 'none' : '';
      t.webview.style.display = (collapsed && t.id !== activeTabId) ? 'none' : t.webview.style.display;
    }
  });
}

function _sortTabsByPinAndGroup() {
  var tabsBar = document.querySelector('.tabs-bar');
  var newTabBtn = document.getElementById('newTabBtn');
  tabs.sort(function(a, b) {
    if (a.pinned && !b.pinned) return -1;
    if (!a.pinned && b.pinned) return 1;
    if (a.groupId && b.groupId) {
      if (a.groupId === b.groupId) return 0;
      var ga = _tabGroups.findIndex(function(g) { return g.id === a.groupId; });
      var gb = _tabGroups.findIndex(function(g) { return g.id === b.groupId; });
      return ga - gb;
    }
    if (a.groupId && !b.groupId) return -1;
    if (!a.groupId && b.groupId) return 1;
    return 0;
  });
  var _savedTabbarBtns = [];
  var _oldTbb = document.getElementById('tabsBarBtns');
  if (_oldTbb) {
    _oldTbb.querySelectorAll('.nav-btn').forEach(function(btn) {
      var foundKey = null;
      if (_currentToolbarButtons) {
        _currentToolbarButtons.forEach(function(k) {
          if (_customizeBtnMap[k] && _customizeBtnMap[k].el === btn.id) foundKey = k;
        });
      }
      if (foundKey && _customizeBtnMap[foundKey] && _customizeBtnMap[foundKey].side === 'tabbar') {
        _savedTabbarBtns.push(btn);
      }
    });
  }
  tabsBar.innerHTML = '';
  tabsBar.appendChild(newTabBtn);
  var _tbbNew = document.createElement('div');
  _tbbNew.className = 'tabs-bar-btns';
  _tbbNew.id = 'tabsBarBtns';
  tabsBar.appendChild(_tbbNew);
  tabs.forEach(function(t) {
    tabsBar.insertBefore(t.element, newTabBtn);
  });
  _renderTabGroupHeaders();
  _savedTabbarBtns.forEach(function(btn) {
    _tbbNew.appendChild(btn);
  });
}

function _updatePinStyle(tabId) {
  var tab = tabs.find(function(t) { return t.id === tabId; });
  if (!tab) return;
  var el = tab.element;
  var titleEl = el.querySelector('.tab-title');
  var closeEl = el.querySelector('.tab-close');
  var audioEl = el.querySelector('.tab-audio');
  if (tab.pinned) {
    el.classList.add('tab-pinned');
    if (titleEl) titleEl.style.display = 'none';
    if (closeEl) closeEl.style.display = 'none';
    if (audioEl) audioEl.style.display = 'none';
  } else {
    el.classList.remove('tab-pinned');
    if (titleEl) titleEl.style.display = '';
    if (closeEl) closeEl.style.display = '';
  }
}

function _applyGroupColor(tabId) {
  var tab = tabs.find(function(t) { return t.id === tabId; });
  if (!tab) return;
  var el = tab.element;
  el.style.removeProperty('border-left');
  if (tab.groupId) {
    var group = _tabGroups.find(function(g) { return g.id === tab.groupId; });
    if (group) {
      el.style.borderLeft = '3px solid ' + (group.color || '#4a90d9');
    }
  }
}

function getTabSleepTimeout() {
  var t = _optSettings.tabSleepTime;
  if (!t || t === 0) return 0;
  return parseInt(t) || 1500000;
}
function resetTabSleepTimer(tabId) {
  if (_tabSleepTimers[tabId]) clearTimeout(_tabSleepTimers[tabId]);
  var sleepTime = getTabSleepTimeout();
  if (sleepTime <= 0) return;
  _tabSleepTimers[tabId] = setTimeout(function() {
    var tab = tabs.find(function(t) { return t.id === tabId; });
    if (!tab || tab.id === activeTabId) return;
    if (!tab.webview || !tab.isReady) return;
    tab.webview.executeJavaScript(
      '(function(){' +
      'var vs=document.querySelectorAll("video");' +
      'for(var i=0;i<vs.length;i++){try{if(!vs[i].paused&&vs[i].currentTime>0)return "playing";}catch(e){}}' +
      'var as=document.querySelectorAll("audio");' +
      'for(var j=0;j<as.length;j++){try{if(!as[j].paused&&as[j].currentTime>0)return "playing";}catch(e){}}' +
      'return "idle";' +
      '})()'
    ).then(function(status) {
      if (status === 'playing') { resetTabSleepTimer(tabId); return; }
      if (tab.lastUrl && tab.lastUrl.indexOf('file://') !== 0 && !isDomainNoSleep(tab.lastUrl)) {
        _maybeClearSWBeforeSleep(tab);
        tab._sleepUrl = tab.lastUrl;
        tab.pendingUrl = tab.lastUrl;
        tab.lastUrl = null;
        try { tab.webview.loadURL('about:blank'); } catch(e) {}
        tab._isSleeping = true;
        var el = document.querySelector('[data-tab-id="' + tabId + '"]');
        if (el) {
          el.classList.add('tab-sleeping');
          var favicon = el.querySelector('.tab-favicon, .tab-favicon-placeholder');
          if (favicon) favicon.classList.add('tab-sleeping-favicon');
        }
      }
    }).catch(function() {});
  }, sleepTime);
}

function wakeUpTab(tab) {
  if (!tab._isSleeping) return;
  tab._isSleeping = false;
  var el = document.querySelector('[data-tab-id="' + tab.id + '"]');
  if (el) {
    el.classList.remove('tab-sleeping');
    var favicon = el.querySelector('.tab-favicon, .tab-favicon-placeholder');
    if (favicon) favicon.classList.remove('tab-sleeping-favicon');
  }
  tab._sleepUrl = null;
  resetTabSleepTimer(tab.id);
}

// ============== PER-TAB AUTO-CLOSE TIMER ==============
var _tabCloseTimers = {};
