// --- Sanitize URL ---
function sanitizeUrlBar(url) {
  if (!_secSettings.sanitizeUrl) return;
  if (!url || url.indexOf('file://') === 0) return;
  var warning = '';
  try {
    var u = new URL(url);
    if (u.username || u.password) warning += 'URL contains credentials. ';
    var host = u.hostname;
    if (host.indexOf('xn--') !== -1) warning += 'Punycode domain — possible phishing. ';
  } catch(e) {}
  if (warning) {
    var urlInput = document.getElementById('urlInput');
    if (urlInput) {
      urlInput.style.borderColor = '#e74c3c';
      urlInput.title = warning;
      setTimeout(function() { urlInput.style.borderColor = ''; urlInput.title = ''; }, 5000);
    }
  }
}

